# In[3]:


"""# DB Connection and File Retrieval"""

import app_settings as app
from psycopg2.pool import SimpleConnectionPool

# Create a connection pool
connection_pool = SimpleConnectionPool(
    1, 10,  # Min and max connections
    dbname=app.postgres['db'],
    user=app.postgres['user'],
    password=app.postgres['password'],
    host=app.postgres['host'],
    port=app.postgres['port']
)

def fetch_data_from_database(data_label, query):
  df = None  # Initialize df
  try:
      # Get a connection from the pool
      conn = connection_pool.getconn()
      try:
          df = pd.read_sql_query(query, conn)
          return df  # Return immediately if successful
      except Exception as e:
          print(f"Error during fetching {data_label}: {e}")
          return None  # Explicitly return None on error
      finally:
          # Return the connection to the pool
          connection_pool.putconn(conn)
          if df is not None:
            print(f"{data_label} fetched")
  except Exception as pool_error:
      print(f"Error getting connection from pool: {pool_error}")
      return None


