# CALCULATIONS FOR REQUIRED COLUMNS
def calculation_formulas(df):
    column_name = f'{report_month}-{report_year}'
    if column_name in df.columns:
        df['current_month_actuals'] = df[column_name]
    else:
        df['current_month_actuals'] = 0 # fill with 0 if empty
    if 'annual_targets' in df.columns and 'monthly_targets' in df.columns and 'ytd_target' in df.columns:
        # Fill any NaNs in required columns with 0 before division
        # df['annual_targets'] = df.get('annual_targets', 0).fillna(0)
        # df['monthly_targets'] = df.get('monthly_targets', df['annual_targets'] / 12).fillna(0) # if it doesn't exist, divide annual target.
        # df['current_month_actuals'] = df['current_month_actuals'].fillna(0)
    
        df['current_month_score'] = (
            df['current_month_actuals'] / df['monthly_targets'].replace({0: np.nan})
        ).clip(lower=0, upper=1.2).fillna(0)
    
        df['ytd_actual'] = df['ytd_actual'] if 'ytd_actual' in df else 0
        df['ytd_actual'] = df['ytd_actual'].fillna(0)
        
        df['ytd_score'] = (
            df['ytd_actual'] / df['ytd_target'].replace({0: np.nan})
        ).clip(lower=0, upper=1.2).fillna(0)

    else:
        df['annual_targets'] = df.get('annual_targets', 0).fillna(0)
        # df['monthly_targets'] = df.get('monthly_targets', df['annual_targets'] / 12).fillna(0) # if it doesn't exist, divide annual target.
        df['current_month_actuals'] = df['current_month_actuals'].fillna(0)
    
        df['current_month_score'] = (
            df['current_month_actuals'] / df['monthly_targets'].replace({0: np.nan})
        ).clip(lower=0, upper=1.2).fillna(0)
    
        df['ytd_target'] = df['annual_targets'] * df['ytd_fraction']
        # df['ytd_actual'] = df.get('ytd_actual', 0).fillna(0)
        df['ytd_actual'] = df['ytd_actual'] if 'ytd_actual' in df else 0
        df['ytd_actual'] = df['ytd_actual'].fillna(0)
        
        df['ytd_score'] = (
            df['ytd_actual'] / df['ytd_target'].replace({0: np.nan})
        ).clip(lower=0, upper=1.2).fillna(0)

    return df



