# DPA CALCULATIONS FOR REQUIRED COLUMNS (it has an mtd_target column)

def dpa_calculation_formulas(df):
    column_name = f'{report_month}-{report_year}' # this gives current month and current year
    
    if column_name in df.columns:
        df['current_month_actuals'] = df[column_name]

    else:
        df['current_month_actuals'] = 0

    if 'annual_targets' in df.columns and 'monthly_targets' in df.columns and 'ytd_target' in df.columns:
        df['annual_targets'] = df.get('annual_targets',0).fillna(0).astype(float)
        df['monthly_targets'] = df.get('monthly_targets',0).fillna(0)
         
        df['current_month_score'] = (df['current_month_actuals'] / df['monthly_targets'].replace({0: np.nan})).clip(lower=0, upper=1.2).fillna(0).astype(float)
        # df['ytd_target'] = (df['annual_targets'] * df['ytd_fraction'])
        df['mtd_target'] = (df['monthly_targets'] * mtd_fraction)
        if 'ytd_actual' in df.columns:
            df['ytd_score'] = (df['ytd_actual'] / df['ytd_target'].replace({0: np.nan})).clip(lower=0, upper=1.2).fillna(0).astype(float)
        else:
            df['ytd_score'] =0

    else:

        df['annual_targets'] = df.get('annual_targets',0)
        df['monthly_targets'] = df.get('monthly_targets',0)
         
        df['current_month_score'] = (df['current_month_actuals'] / df['monthly_targets'].replace({0: np.nan})).clip(lower=0, upper=1.2).fillna(0).astype(float)
        df['ytd_target'] = (df['annual_targets'] * df['ytd_fraction'])
        df['mtd_target'] = (df['monthly_targets'] * mtd_fraction)
        if 'ytd_actual' in df.columns:
            df['ytd_score'] = (df['ytd_actual'] / df['ytd_target'].replace({0: np.nan})).clip(lower=0, upper=1.2).fillna(0).astype(float)
        else:
            df['ytd_score'] =0

    return df


