# DPA TEAM LEADERS CALCULATIONS FOR REQUIRED COLUMNS (their annual targets depend on the number of persons in the team or number modified by line manager)

def dpa_team_leaders_calculation_formulas(df):
    column_name = f'{report_month}-{report_year}' # this gives current month and current year
    if column_name in df.columns:
        df['current_month_actuals'] = df[column_name]

    else:
        df['current_month_actuals'] = 0

    if 'monthly_targets' in df.columns:
        dpa_persons_count = 10  # 10 is the allocated (by line manager)  number of persons for each as at July 2025 & 12 is the number of months in a year
        df['annual_targets'] = (df['monthly_targets'] * (dpa_persons_count*12))  
        df['monthly_targets'] = df['annual_targets']/12
        df['current_month_score'] = (df['current_month_actuals'] / df['monthly_targets']).clip(lower= 0,upper=1.2)
        df['ytd_target'] = df['annual_targets'] * ytd_fraction
        df['mtd_target'] = df['monthly_targets'] * mtd_fraction
        if 'ytd_actual' in df.columns:
            df['ytd_score'] = (df['ytd_actual'] / df['ytd_target']).clip(lower=0,upper=1.2)
        else:
            df['ytd_score'] =0

    else:
        df['current_month_score'] = (df['current_month_actuals'] / df['monthly_targets']).clip(lower= 0,upper=1.2)
        df['ytd_target'] = df['annual_targets'] * ytd_fraction
        df['mtd_target'] = df['monthly_targets'] * mtd_fraction
        if 'ytd_actual' in df.columns:
            df['ytd_score'] = (df['ytd_actual'] / df['ytd_target']).clip(lower=0,upper=1.2)
        else:
            df['ytd_score'] =0

    return df


