# In[14]:


def roles_total_row(df):

    df['annual_targets'] = df.get('annual_targets', 0).fillna(0)
    df['monthly_targets'] = df.get('monthly_targets', 0).fillna(0)
    total_row = df.sum(numeric_only=True)

    # handle division of 0 by 0 for current month score
    numerator_1 = df['current_month_actuals'].sum()
    denominator_1 = df['monthly_targets'].sum()

    if denominator_1 == 0 and numerator_1 == 0:
        month_ratio = 0
    elif denominator_1 == 0:
        month_ratio = 0
    else:
        month_ratio = numerator_1 / denominator_1

    total_row['current_month_score'] = float(np.clip(month_ratio, 0, 1.2))

    # handle division of 0 by 0
    numerator_2 = df.get('ytd_actual', pd.Series(0)).sum()
    denominator_2 = df.get('ytd_target', pd.Series(0)).sum()

    if denominator_2 == 0 and numerator_2 == 0:
        year_ratio = 0
    elif denominator_2 == 0:
        year_ratio = 0
    else:
        year_ratio = numerator_2 / denominator_2

    total_row['ytd_score'] = float(np.clip(year_ratio, 0, 1.2))

    # 
    total_row = pd.DataFrame(total_row).T
    total_row.index = ['Total']
    total_row = total_row.fillna(" ")
    df = pd.concat([df, total_row], axis=0)

    return df


# In[15]:


# RANK THE SALESPERSONS
def rank_performance(dataframe,sort_column):
    # Exclude the Total row
    df_without_last_row = dataframe.iloc[:-1].copy()
    df_without_last_row['rank'] = df_without_last_row[sort_column].rank(ascending=False, method='dense')

    # Sort the new DataFrame by 'rank'
    sorted_df = df_without_last_row.sort_values(by='rank')
    sorted_df['rank'] = pd.to_numeric(sorted_df['rank'], errors='coerce')
    sorted_df['rank'] = sorted_df['rank'].astype(float).astype(int)

    # Get the Total row
    last_row = dataframe.iloc[-1:]

    # Reattach the Total row to the sorted DataFrame
    result_df = pd.concat([sorted_df, last_row])
    result_df = result_df.reindex(['rank']+[column for column in result_df.columns if column not in ['rank']], axis=1)

    return result_df

# VINTAGE FOR PAYMENT TEAM & PB DSRS
def get_vintage(row):  # duration they've been in the organisation
    joining_date = pd.to_datetime(row['employment_date'])
    current_date = pd.to_datetime(report_date, format='%d-%b-%Y')
    
    months_in_role = ((current_date.year- joining_date.year)* 12 + (current_date.month- joining_date.month)) # sums the number of months employed

    if months_in_role > 18:
        return 'Above 18 months'
    elif months_in_role >= 15 and months_in_role <= 18:
        return '15 to 18 months'
    elif months_in_role >= 12 and months_in_role < 15:
        return '12 to 15 months'
    elif months_in_role >= 9 and months_in_role < 12:
        return '9 to 12 months'
    elif months_in_role >= 6 and months_in_role < 9:
        return '6 to 9 months'
    elif months_in_role >= 4 and months_in_role < 6:
        return '4 to 6 months'
    else :
        return '3 months and below'
        


