#function for zerorizing targets for sales persons returning in same role
def zero_out_return_salespersons_in_same_role(pivot_df, report_year):
    # List of promoted salespeople
    sales_codes_jul = ['DSR309'] # Dius Muraguri
    # promoted_sales_codes_jul = ['AWM1991']

    # Define which months to zero out
    months_to_zero_jun = [f'{month}-{report_year}' for month in ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun']]
    # months_to_zero_jul = [f'{month}-{report_year}' for month in ['Jan', 'Feb', 'Mar', 'Apr','May', 'Jun','Jul']]

    # Ensure we only zero out columns that exist
    columns_to_zero_jun = [col for col in months_to_zero_jun if col in pivot_df.columns]
    # columns_to_zero_jul = [col for col in months_to_zero_jul if col in pivot_df.columns]

    # Apply zeroing logic for each group
    pivot_df.loc[pivot_df['sales_code'].isin(sales_codes_jul), columns_to_zero_jun] = 0
    # pivot_df.loc[pivot_df['sales_code'].isin(promoted_sales_codes_jul), columns_to_zero_jul] = 0

    # Recalculate 'total' for all rows (or optionally only for affected rows)
    month_columns = [col for col in pivot_df.columns if col not in ['sales_code', 'total'] and '-' in col]
    pivot_df['total'] = pivot_df[month_columns].sum(axis=1)

    return pivot_df


