                  # full targets for all metrics onwards(from month 11)
          
def calculate_targets_for_dsrs_new_model(df,monthly_target_columns,report_date,
                                         zero_loan_deposit_banca_columns=['target_loan_disbursement','target_banca_life','target_banca_non_life','target_properties','target_banca_value']):

    current_date = pd.to_datetime(report_date, format='%d-%b-%Y')

    if zero_loan_deposit_banca_columns is None:
        zero_loan_deposit_banca_columns = []

    # Iterate over each row in the dataframe
    for idx, row in df.iterrows():

        employment_date = pd.to_datetime(row['employment_date'], errors='coerce')
        role = row['staff_role']

        if pd.isna(employment_date):
            continue
         # the new model was first adopted for any sales persons who joined from Aug 2025 then the half targets logic has been updated from Feb 2026
        if role in ['PB DSR', 'SME DSR'] and employment_date >= pd.Timestamp('2025-08-01'):
            role = f"{role} New"
            df.at[idx, 'staff_role'] = role

        if role not in ['PB DSR New', 'SME DSR New']:
            continue
            
        months_since_employment = ((current_date.year - employment_date.year) * 12 +(current_date.month - employment_date.month)) + 1

        # for the first month(employment date), no targets are applied. they start from the 2nd month
        if months_since_employment <= 1:
            multiplier = 0

        elif 2 <= months_since_employment <= 10:
            multiplier = 0.5

        else:
            multiplier = 1.0 # full targets are applied from the 11 month(1st month no targets,3+6 months half targets) =10

        for col in monthly_target_columns:

            if col not in df.columns:
                continue

            base_target = row.get(col, 0)

            # apply zero targets on the first month
            if months_since_employment <= 1:
                df.at[idx, col] = 0

            # it was agreed that no targets will be applied for loans, banca & properties for the 1st 3 months as it is hard to sell
            elif 2 <= months_since_employment <= 4 and col in zero_loan_deposit_banca_columns:
                df.at[idx, col] = 0

            else:
                df.at[idx, col] = base_target * multiplier

    return df


