# In[23]:


def calculate_annual_targets_including_promoted(
    group,
    monthly_target_columns,
    mtd_date,
    # Home specialist targets
    specialist_loans_probation_target=15000000,  
    specialist_loans_zero_months=2,  
    specialist_loans_probation_months=3, 
    specialist_approvals_probation_target=20000000,  
    specialist_approvals_probation_months=5,
):
  

    annual_targets = {
        "recalculated_target_loan_disbursement": 0,
        "recalculated_target_loan_approvals": 0,
    }

    # --- For DSR roles ---
    if group.iloc[0]['staff_role'] in ['PB DSR', 'SME DSR']:
        row = group.iloc[0]
        employment_date = pd.to_datetime(row['employment_date'])
        new_model_introduction_date = pd.Timestamp('2025-08-01')

        sales_code = row['sales_code']

        maternity_months = MATERNITY_MONTHS.get(sales_code, [])

        if maternity_months:
            maternity_end = max(maternity_months)
            half_target_months = [
                m for m in range(maternity_end + 1, maternity_end + 4)
                if m <= 12
            ]
        else:
            half_target_months = []

        for target_column in monthly_target_columns:
            monthly_target = row.get(target_column, 0) or 0
            total_weighted_target = 0

            for month in range(1, 13):

                report_month_date = pd.Timestamp(
                    year=mtd_date.year,
                    month=month,
                    day=1
                )

                # Maternity logic takes precedence
                if month in maternity_months:
                    target_weight = 0.0

                elif month in half_target_months:
                    target_weight = 0.5

                # Existing employment logic
                elif report_month_date < employment_date.replace(day=1):
                    target_weight = 0.0

                elif (
                    employment_date.year == report_month_date.year
                    and employment_date.month == report_month_date.month
                    and employment_date.day > 1
                ):
                    target_weight = 0.0

                else:
                    months_since_employment = (
                        (report_month_date.year - employment_date.year) * 12
                        + (report_month_date.month - employment_date.month)
                    )

                    target_weight = (
                        0.5
                        if (
                            employment_date < new_model_introduction_date
                            and months_since_employment <= 6
                        )
                        else 1.0
                    )

                total_weighted_target += target_weight * monthly_target

            annual_targets[f'annual_{target_column}'] = total_weighted_target

        return pd.Series(annual_targets)

    # --- For all other roles (Specialists + promotions) ---
    report_year = mtd_date.year
    for target_column in monthly_target_columns:
        annual_targets[f'annual_{target_column}'] = 0

    # --- Loop through each role entry (promotions) ---
    for _, row in group.iterrows():
        start_date = pd.to_datetime(row['start_date'])
        end_date = (
            pd.to_datetime(row['exit_date'])
            if pd.notnull(row['exit_date'])
            else pd.Timestamp(year=report_year, month=12, day=31)
        )

        role_start = max(start_date, pd.Timestamp(year=report_year, month=1, day=1))
        role_end = min(end_date, pd.Timestamp(year=report_year, month=12, day=31))
        if role_start > role_end:
            continue

        months_active = (
            (role_end.year - role_start.year) * 12
            + (role_end.month - role_start.month)
            + 1
        )

        employment_date = pd.to_datetime(row['employment_date'])

        months_since_employment_at_mtd = (
            (mtd_date.year - employment_date.year) * 12
            + (mtd_date.month - employment_date.month)
        )

        for target_column in monthly_target_columns:
            monthly_target = row.get(target_column, 0) or 0
            staff_role = str(row.get('staff_role', '')).upper()

            # Mortgage Business
            if any(x in staff_role for x in ['MORTGAGE ARM', 'MORTGAGE RM']):

                # Annual target
                total = 0
                for month in range(role_start.month, role_end.month + 1):
                    report_month_date = pd.Timestamp(year=report_year, month=month, day=1)

                    months_since_employment = (
                        (report_month_date.year - employment_date.year) * 12
                        + (report_month_date.month - employment_date.month)
                    )

                    if target_column.lower() == 'target_loan_disbursement':
                        if months_since_employment < specialist_loans_zero_months:
                            month_target = 0
                        elif months_since_employment < specialist_loans_zero_months + specialist_loans_probation_months:
                            month_target = specialist_loans_probation_target
                        else:
                            month_target = monthly_target

                    elif target_column.lower() == 'target_loan_approvals':
                        if months_since_employment < specialist_approvals_probation_months:
                            month_target = specialist_approvals_probation_target
                        else:
                            month_target = monthly_target
                    else:
                        month_target = monthly_target

                    total += month_target

                annual_targets[f'annual_{target_column}'] += total

                # Current month recalculation
                if role_start.month <= mtd_date.month <= role_end.month:
                    if target_column.lower() == 'target_loan_disbursement':
                        if months_since_employment_at_mtd < specialist_loans_zero_months:
                            recalculated = 0
                        elif months_since_employment_at_mtd < specialist_loans_zero_months + specialist_loans_probation_months:
                            recalculated = specialist_loans_probation_target
                        else:
                            recalculated = monthly_target

                        annual_targets["recalculated_target_loan_disbursement"] = recalculated

                    elif target_column.lower() == 'target_loan_approvals':
                        if months_since_employment_at_mtd < specialist_approvals_probation_months:
                            recalculated = specialist_approvals_probation_target
                        else:
                            recalculated = monthly_target

                        annual_targets["recalculated_target_loan_approvals"] = recalculated

            # --- Non-specialist roles ---
            else:
                annual_targets[f'annual_{target_column}'] += monthly_target * months_active

    return pd.Series(annual_targets)

