def zero_out_promoted_salespersons(pivot_df, report_year, zeroout_df):
    # Month order for comparison
    month_order = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 
                  'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
    
    # Group sales codes by their start month
    sales_by_month = {}
    for _, row in zeroout_df.iterrows():
        try:
            sales_code = row['sales_code']
            start_date = row['start_date']
            
            if isinstance(start_date, str):
                start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
            else:
                start_date_obj = start_date
            
            if start_date_obj.year != report_year:
                continue
                
            start_month = start_date_obj.month
            if start_month not in sales_by_month:
                sales_by_month[start_month] = []
            sales_by_month[start_month].append(sales_code)
            
        except Exception as e:
            print(f"Error processing {row['sales_code']}: {e}")
            continue
    
    # Apply zeroing logic for each month group
    for start_month, sales_codes in sales_by_month.items():
        if not sales_codes:
            continue
            
        # Determine which months to zero out (all months before start_month - 1)
        cutoff_month = start_month - 1
        months_to_zero = []
        
        for month_num in range(1, 13):  # January to December
            if month_num < cutoff_month:
                month_name = month_order[month_num - 1]
                months_to_zero.append(f'{month_name}-{report_year}')
        
        # Ensure we only zero out columns that exist
        columns_to_zero = [col for col in months_to_zero if col in pivot_df.columns]
        
        if columns_to_zero:
            pivot_df.loc[pivot_df['sales_code'].isin(sales_codes), columns_to_zero] = 0
    
    # Recalculate 'total' for all rows
    month_columns = [col for col in pivot_df.columns if col not in ['sales_code', 'total'] and '-' in col]
    pivot_df['total'] = pivot_df[month_columns].sum(axis=1)

    return pivot_df


