def calculate_monthly_weights_upto_dec(row, mtd_date):

    employment_date = pd.to_datetime(row['employment_date'])
    monthly_weights = {}

    sales_code = row['sales_code'] 

    if row['staff_role'] not in ['PB DSR', 'SME DSR']:
        for month in range(1, 13):
            report_month_date = pd.Timestamp(year=mtd_date.year,month=month,day=1)
            month_label = f'{report_month_date.strftime("%b")}_weight'
            monthly_weights[month_label] = 1.0

        return pd.Series(monthly_weights)

    # maternity month targets(half targets for 3 months after reporting back as guided by Ngila)   
    maternity_months = MATERNITY_MONTHS.get(sales_code, [])
    if maternity_months:
        maternity_end = max(maternity_months)
        half_target_months = [m for m in range(maternity_end + 1, maternity_end + 4)if m <= 12]
    else:
        half_target_months = []

    for month in range(1, 13):

        report_month_date = pd.Timestamp(year=mtd_date.year,month=month,day=1)

        month_label = f'{report_month_date.strftime("%b")}_weight'

        # Maternity logic takes precedence
        if month in maternity_months:
            weight = 0.0

        elif month in half_target_months:
            weight = 0.5

        elif report_month_date < employment_date.replace(day=1):
            weight = 0.0

        elif (employment_date.year == report_month_date.year and report_month_date.month == employment_date.month and employment_date.day > 1):
            weight = 0.0

        else:
            months_since_employment = ((report_month_date.year - employment_date.year) * 12 + (report_month_date.month - employment_date.month))

            weight = 0.5 if months_since_employment <= 6 else 1.0

        monthly_weights[month_label] = weight

    return pd.Series(monthly_weights)


