# In[39]:


def merge_dfs(*dfs, on="sales_code", branch_col="branch", sort_sales_codes=True):
    """
    Align multiple DataFrames on branch + sales_code while keeping them independent.

    Args:
        *dfs: Variable number of DataFrames
        on (str): Column to align on (default = 'sales_code')
        branch_col (str): Column to group/sort by before sales_code
        sort_sales_codes (bool): Sort values if True

    Returns:
        list of aligned DataFrames (same order as input)
    """
    # collect all combinations of branch + sales_code
    all_codes = (
        pd.concat([df[[branch_col, on]].copy() for df in dfs], ignore_index=True)
        .drop_duplicates()
    )

    # separate total rows (NaN sales_code)
    total_rows = all_codes[all_codes[on].isna()]
    all_codes = all_codes[all_codes[on].notna()]

    # clean invalid codes
    all_codes = all_codes[
        all_codes[on].astype(str).str.strip().ne("0") &
        all_codes[on].astype(str).str.strip().ne("")
    ]

    if sort_sales_codes:
        # case-insensitive sorting
        all_codes = (
            all_codes.assign(
                branch_sort=all_codes[branch_col].astype(str).str.upper(),
                code_sort=all_codes[on].astype(str).str.upper()
            )
            .sort_values(by=["branch_sort", "code_sort"])
            .drop(columns=["branch_sort", "code_sort"])
        )

    # reattach total rows at bottom
    all_codes = pd.concat([all_codes, total_rows], ignore_index=True)

    aligned_dfs = []
    for df in dfs:
        df_aligned = df.copy()

        # normalize types for safe merge
        df_aligned[on] = df_aligned[on].where(
            df_aligned[on].isna(), df_aligned[on].astype(str)
        )

        df_aligned = pd.merge(
            all_codes,
            df_aligned,
            on=[branch_col, on],
            how="left"
        )

        aligned_dfs.append(df_aligned)

    return aligned_dfs


# In[40]:


def merge_teamleader_dfs(*dfs, on="team_leader", sort_sales_codes=True):
    """
    Align multiple DataFrames on a common column while keeping them independent.

    Args:
        *dfs: Variable number of DataFrames
        on (str): Column to align on (default = 'sales_code')
        sort_sales_codes (bool): Sort codes alphabetically if True

    Returns:
        list of aligned DataFrames (same order as input)
    """
    # collect all sales_codes across DataFrames
    all_codes = pd.concat([df[[on]].copy() for df in dfs]).drop_duplicates()

    # separate total row (NaN sales_code)
    total_row = all_codes[all_codes[on].isna()]
    all_codes = all_codes[all_codes[on].notna()]

    # remove accidental "0" or blank codes
    all_codes = all_codes[all_codes[on].astype(str).str.strip().ne("0")]

    if sort_sales_codes:
        # Create a temporary column for case-insensitive sorting
        all_codes['temp_sort'] = all_codes[on].str.upper()
        all_codes = all_codes.sort_values(by='temp_sort').drop('temp_sort', axis=1)

    # reattach total row at bottom
    all_codes = pd.concat([all_codes, total_row], ignore_index=True)

    aligned_dfs = []
    for df in dfs:
        df_aligned = df.copy()

        # convert only non-NaN codes to string
        df_aligned[on] = df_aligned[on].where(
            df_aligned[on].isna(), df_aligned[on].astype(str)
        )

        df_aligned = pd.merge(all_codes, df_aligned, on=on, how="left")
        aligned_dfs.append(df_aligned)

    return aligned_dfs


