# In[42]:


def merge_within_lists(*df_lists, on="sales_code", branch_col="branch", sort_sales_codes=True):
    """
    Align DataFrames across multiple lists by sales_code,
    keeping lists independent but ensuring that DataFrames
    in the same position (index) share the same sales_codes.

    Args:
        *df_lists: Variable number of lists of DataFrames
        on (str): Column to align on (default = 'sales_code')
        branch_col (str): Column to sort by before sales_code
        sort_sales_codes (bool): Sort codes if True

    Returns:
        tuple of aligned lists (same structure as input)
    """
    n = len(df_lists[0])  # assume all lists have the same length
    merged_lists = [[] for _ in df_lists]

    for i in range(n):  
        # collect sales_codes (+ branch) from each list's ith DataFrame
        all_codes = pd.concat([
            lst[i][[branch_col, on]].copy() for lst in df_lists
        ]).drop_duplicates()

        # separate total row (NaN sales_code)
        total_row = all_codes[all_codes[on].isna()]
        all_codes = all_codes[all_codes[on].notna()]

        # remove accidental "0" or blank codes
        all_codes = all_codes[all_codes[on].astype(str).str.strip().ne("0")]

        if sort_sales_codes:
            # temp columns for case-insensitive sorting
            all_codes["branch_sort"] = all_codes[branch_col].astype(str).str.upper()
            all_codes["code_sort"] = all_codes[on].astype(str).str.upper()

            all_codes = (
                all_codes
                .sort_values(by=["branch_sort", "code_sort"])
                .drop(columns=["branch_sort", "code_sort"])
            )

        # reattach total row at bottom
        all_codes = pd.concat([all_codes, total_row], ignore_index=True)

        # align each list's ith DataFrame
        for j, lst in enumerate(df_lists):
            df_aligned = lst[i].copy()

            # convert only non-NaN codes to string
            df_aligned[on] = df_aligned[on].where(
                df_aligned[on].isna(), df_aligned[on].astype(str)
            )

            df_aligned = pd.merge(all_codes, df_aligned, on=[branch_col, on], how="left")
            merged_lists[j].append(df_aligned)

    return tuple(merged_lists)


# In[43]:


def drop_column_from_dfs(dfs, column_name):
    """
    Drop a column from multiple DataFrames if it exists.

    Args:
        dfs (list): List/tuple of DataFrames
        column_name (str): Column to drop

    Returns:
        list of DataFrames with the column removed
    """
    cleaned_dfs = []
    for df in dfs:
        if column_name in df.columns:
            cleaned_dfs.append(df.drop(columns=[column_name]))
        else:
            cleaned_dfs.append(df.copy())  # keep unchanged
    return cleaned_dfs


# In[44]:


def drop_column_from_lists(dfs, column_name):
    """
    Drop a column from multiple DataFrames (nested in lists/tuples) if it exists.

    Args:
        dfs (list or tuple): List/tuple of DataFrames, or nested lists/tuples of DataFrames.
        column_name (str): Column to drop

    Returns:
        list: Same structure as input, with the column removed from any DataFrame that had it.
    """
    cleaned = []

    for item in dfs:
        if isinstance(item, (list, tuple)):
            # Recursive call for nested list/tuple
            cleaned.append(drop_column_from_dfs(item, column_name))
        elif isinstance(item, pd.DataFrame):
            if column_name in item.columns:
                cleaned.append(item.drop(columns=[column_name]))
            else:
                cleaned.append(item.copy())
        else:
            raise TypeError(f"Unsupported type: {type(item)}. Expected DataFrame or list/tuple.")

    return cleaned


# In[45]:


def apply_current_month_weights(row, target_columns, mtd_date):
    """
    Applies the current month's weight to the specified target columns.
    Overwrites the original values in the row.

    Args:
        row (pd.Series): A row from the DataFrame.
        product_target_columns (list): List of target columns (e.g., ['new_customers_target']).
        mtd_date (datetime): Month-to-date reference date.

    Returns:
        pd.Series: The updated row with weighted targets.
    """
    # Construct the current month's weight column name (e.g., "Aug_weight")
    current_month = mtd_date.strftime("%b")  # 'Aug'
    weight_column = f"{current_month}_weight"

    # Make a copy to modify
    result_row = row.copy()

    try:
        weight = row[weight_column]

        # If Series (duplicate column names), use the first
        if isinstance(weight, pd.Series):
            print(f"[Warning] Duplicate weight column '{weight_column}' detected. Using first value.")
            weight = weight.iloc[0]

        weight = float(weight)

        if pd.isna(weight):
            raise ValueError(f"Weight is NaN for staff '{row.get('staff_name', 'unknown')}'.")

    except KeyError:
        print(f"[Warning] Weight column '{weight_column}' not found for staff '{row.get('staff_name', 'unknown')}'.")
        return row
    except ValueError as ve:
        print(f"[Warning] {ve}")
        return row

    # Apply weight to each target column
    for col in target_columns:
        if col not in row:
            print(f"[Warning] Target column '{col}' not found in row.")
            continue

        try:
            value = row[col]

            # Handle duplicates
            if isinstance(value, pd.Series):
                print(f"[Warning] Duplicate target column '{col}' detected. Using first value.")
                value = value.iloc[0]

            if pd.isna(value):
                value = 0.0
            else:
                value = float(value)

            # Overwrite with weighted value
            result_row[col] = value * weight

        except Exception as e:
            print(f"[Error] Failed to apply weight to '{col}' for staff '{row.get('staff_name', 'unknown')}': {e}")

    return result_row


