"""

# Data Processing Functions

## Accounts Data
"""

def process_daily_accounts_dataframe(weighted_cto):
    #all staff - both active& exits
    columns_to_keep= ['sales_code','staff_name','staff_role','team_leader']
    accounts_sales_person_mapping=sales_persons_targets_mapping_unique[columns_to_keep]




    
    # weighted_cto['cust_open_date'] = pd.to_datetime( weighted_cto['cust_open_date']).dt.strftime('%d-%m-%Y')
    # weighted_cto['acc_open_date'] = pd.to_datetime( weighted_cto['acc_open_date']).dt.strftime('%d-%m-%Y')
    
    weighted_cto['cust_open_date'] = pd.to_datetime( weighted_cto['cust_open_date'])
    weighted_cto['acc_open_date'] = pd.to_datetime( weighted_cto['acc_open_date'])

    # remove spaces form sales code column
    weighted_cto['sale_code'] = weighted_cto['sale_code'].apply(lambda x: x.replace(" ",""))

    # correct the sales codes in the data
    weighted_cto.loc[weighted_cto['sale_code'] == 'AL3116','sale_code']= 'AKL3116'
    weighted_cto.loc[weighted_cto['sale_code'] == 'SC3568','sale_code']= 'SJC3568'
    weighted_cto.loc[weighted_cto['sale_code'] == 'PK3453','sale_code']= 'PMK3453'
    weighted_cto.loc[weighted_cto['sale_code'] == 'AOL3199','sale_code']= 'AL3199'

    #from customer segment remove staff and internal accounts from the data
    filtered_weighted_cto = weighted_cto[(weighted_cto['customer_segment']!='STAFF' ) & (weighted_cto['customer_segment']!='INTERNAL ACCOUNTS')]
    filtered_weighted_cto= filtered_weighted_cto.fillna(0)
    filtered_weighted_cto.shape[0]

    # find the difference between closing balance for the previous year and current balance
    filtered_weighted_cto['difference'] = filtered_weighted_cto['current_year_bal'] - filtered_weighted_cto['prev_year_dec_bal']

    # check if customer is new/ if they didn't have an existing account before reporting year
    filtered_weighted_cto['new_customer_check'] = np.where(filtered_weighted_cto['total_accounts_before_current_year'] == 0, "Y","N")

    def new_value(row):
        if row['bal'] < 0:
            return 0
        elif row['new_customer_check'] =="Y":
            return row['bal']
        elif (row['new_customer_check'] =="N") & (row['difference'] < 0):
            return 0
        else:
            return row['bal']

    filtered_weighted_cto['new_value'] = filtered_weighted_cto.apply(new_value, axis = 1)

    # filtered_weighted_cto['customer_date'] = pd.to_datetime(filtered_weighted_cto['cust_open_date'], dayfirst =True).dt.strftime('%b-%Y')
    filtered_weighted_cto['customer_date'] = filtered_weighted_cto['cust_open_date'].dt.strftime('%b-%Y')
    filtered_weighted_cto['account_date'] = filtered_weighted_cto['acc_open_date'].dt.strftime('%b-%Y')

    # account is funded if balance is above zero
    def account_funded_check(row):
        if row['bal'] > 0 or row['account_cto'] > 0 :
            return "F"
        else:
            return "N"

    filtered_weighted_cto['acc_funded_check'] = filtered_weighted_cto.apply(account_funded_check, axis = 1)

    def customer_funded_check(row):
        if row['cust_cto'] > 0 or row['current_year_bal'] > 0 :
            return "F"
        else:
            return "N"

    filtered_weighted_cto['customer_funded_check'] = filtered_weighted_cto.apply(customer_funded_check, axis = 1)

    filtered_weighted_cto = pd.merge(filtered_weighted_cto,product_mapping, on='prod_id', how='left')
    # correct focus type for the below accounts
    filtered_weighted_cto.loc[filtered_weighted_cto['prod_id']==31805,'focus']='Y'
    filtered_weighted_cto.loc[filtered_weighted_cto['prod_id']==31806,'focus']='Y'
    filtered_weighted_cto.loc[filtered_weighted_cto['prod_id']==31807,'focus']='Y'

    def savings_account(row):
        if row['product_map'] == 'SA':
            return 'Y'
        else:
            return 'N'

    filtered_weighted_cto['savings_account'] = filtered_weighted_cto.apply(savings_account,axis = 1)

    # sme accounts check used for DPAs only
    sme_products = [{'CODE':31551,'PRODUCT_DESCRIPTION':'EASY COLLECT ACCOUNT'},
                    {'CODE':31561,'PRODUCT_DESCRIPTION':'SME BIZ ACCOUNT'},
                    {'CODE':31704,'PRODUCT_DESCRIPTION':'CURRENT ACCOUNT CORPORATE'},
                    {'CODE':31591,'PRODUCT_DESCRIPTION':'TRANSACTIONAL-SME BIZ ACCOUNT'},
                    {'CODE':31809,'PRODUCT_DESCRIPTION':'BIASHARA CURRENT ACCOUNT'},
                    {'CODE':31815,'PRODUCT_DESCRIPTION':'BIASHARA SAVINGS ACCOUNT'}
                  ]

    def get_sme_products_only(row):
        if row['prod_id'] in  [31551,31561,31704,31591,31809,31815]  :
            return 'Y'
        else:
            return 'N'

    filtered_weighted_cto['sme_check'] = filtered_weighted_cto.apply(get_sme_products_only, axis =1)

    filtered_weighted_cto.drop(columns =['product_map'], inplace = True)

    filtered_weighted_cto = filtered_weighted_cto.rename(columns ={'focus':'focus_check'})

    filtered_weighted_cto = pd.merge(filtered_weighted_cto,branch_name_map, on= 'brn_code', how = 'left')
    filtered_weighted_cto = filtered_weighted_cto.rename(columns={'staff_branch':'branch'})

    # map the branch codes: 100 & 109
    filtered_weighted_cto.loc[filtered_weighted_cto['brn_code']==100,'branch']='HO'
    filtered_weighted_cto.loc[filtered_weighted_cto['brn_code']==109,'branch']='VIRTUAL'
    filtered_weighted_cto.loc[filtered_weighted_cto['brn_code']==210,'brn_code']= 19

    # trim spaces in sales codes
    filtered_weighted_cto['sales_code'] = filtered_weighted_cto['sale_code'].str.strip()

    filtered_weighted_cto = pd.merge(filtered_weighted_cto,accounts_sales_person_mapping, on='sales_code', how = 'left')
    filtered_weighted_cto = filtered_weighted_cto.rename(columns ={'staff_name':'sales_name'})

    # anywhere ther's sales code:1SALESMAN, map sales name as virtual
    filtered_weighted_cto.loc[filtered_weighted_cto['sales_code'] == '1SALESMAN','sales_name']= 'VIRTUAL'

    # filtered_weighted_cto = pd.merge(filtered_weighted_cto,dpa_pb_dsr_leader_map, left_on ='sales_code', right_on='code', how='left')
    # filtered_weighted_cto.drop(columns= {'code'}, inplace = True)

    filtered_weighted_cto['duplicate_customer_check'] = filtered_weighted_cto['cust_cif'].duplicated().apply(lambda x: 0 if x else 1)

    # rename the column ensuring they'll change every year
    filtered_weighted_cto = filtered_weighted_cto.rename(columns ={'prev_year_dec_bal':f'{report_year-1}_dec_bal','current_year_bal':f'{report_year}_current_bal',
                                                                  'total_accounts_before_current_year':f'total_accounts_before_{report_year}'})
    filtered_weighted_cto_column_order = ['cust_cif', 'cust_open_date', 'full_name', 'brn_code', 'acc_num','sale_code','prod_id','customer_segment', 'acc_open_date', 
                                          'bal', 'cust_cto','account_cto',f'{report_year-1}_dec_bal',f'{report_year}_current_bal',f'total_accounts_before_{report_year}', 'account_status', 'difference',
                                          'new_customer_check', 'new_value', 'customer_date', 'account_date','acc_funded_check', 'customer_funded_check', 'product_description',
                                          'focus_check', 'savings_account', 'sme_check', 'branch', 'sales_code','sales_name','staff_role', 'team_leader', 'duplicate_customer_check']
    filtered_weighted_cto =filtered_weighted_cto[filtered_weighted_cto_column_order]
    return filtered_weighted_cto

"""## Dormancy Data"""

def process_daily_dormancy_accounts_dataframe(branch_dormancy_report):
    branch_dormancy_report['last_dormant_date'] = pd.to_datetime(branch_dormancy_report['last_dormant_date'], errors='coerce')
    branch_dormancy_report['reactivation_date'] = pd.to_datetime(branch_dormancy_report['reactivation_date'], errors='coerce')
    branch_dormancy_report['reactivation_date'].fillna('01-01-2000', inplace=True)
    branch_dormancy_report = branch_dormancy_report[branch_dormancy_report['customer_segment']!='STAFF']

    # add month activation column
    branch_dormancy_report['month'] = branch_dormancy_report['reactivation_date'].dt.strftime('%b-%Y')
    branch_dormancy_column_order = ['acc_num', 'cust_cif', 'brn_code', 'prod_id', 'full_name','customer_segment', 
                                    'last_dormant_date', 'current_status','current_bal', 'reactivation_date', 'month']
    branch_dormancy_report =branch_dormancy_report[branch_dormancy_column_order]

    return branch_dormancy_report

"""## Drawdown Data"""

def process_daily_drawdown_dataframe(daily_drawdown_report):
    # columns to be used in weighted
#     drawdown_columns_to_keep= ['ACCOUNT_NUMBER', 'CUST_ID', 'CUSTOMER_NAME', 'DRAWDOWN_DT',
#                               'SALES_STAFF', 'ID_PRODUCT', 'PRODUCT_NAME', 'LOAN_OFFICER_ID',
#                               'LOAN_OFFICER_NAME', 'FINAL_INTEREST', 'TOTAL_DAYS', 'LOA',
#                               'UNIT_CODE', 'EOM_DATE', 'NET_DRAWDOWN', 'GROSS_DRAWDOWN', 'SEGMENT',
#                               'FINANCIAL_SECTOR', 'ACTIVITY_SECTOR', 'DIASPORA_CHECK',
#                               'FKGD_CATEGORY', 'DESCRIPTION']
    # daily_drawdown_report = daily_drawdown_report[drawdown_columns_to_keep]

#     daily_drawdown_report = daily_drawdown_report.rename(columns={'ACCOUNT_NUMBER':'account_number', 'CUST_ID':'cust_id', 'CUSTOMER_NAME':'customer_name', 'DRAWDOWN_DT':'drawdown_date',
#                                                                   'SALES_STAFF':'sales_person', 'ID_PRODUCT':'id_product', 'PRODUCT_NAME':'product_name', 'LOAN_OFFICER_ID':'loan_officer_id',
#                                                                   'LOAN_OFFICER_NAME':'loan_officer_name', 'FINAL_INTEREST':'final_interest', 'TOTAL_DAYS':'total_days', 'TOTAL_MONTHS':'loan_term_months',
#                                                                   'UNIT_CODE':'unit_code', 'EOM_DATE':'eom_date', 'NET_DRAWDOWN':'net_drawdown', 'GROSS_DRAWDOWN':'gross_drawdown', 'SEGMENT':'segment',
#                                                                   'FINANCIAL_SECTOR':'financial_sector', 'ACTIVITY_SECTOR':'activity_sector', 'DIASPORA_CHECK':'diaspora_check','FKGD_CATEGORY':'fkgd_category', 'DESCRIPTION':'description'})
   
    filtered_daily_drawdown_report = daily_drawdown_report[(daily_drawdown_report['segment']!='STAFF' ) & (daily_drawdown_report['description']!='Staff') & (daily_drawdown_report['sales_person']!='SBP0001')]
   # rename 1 to OD
    filtered_daily_drawdown_report.loc[filtered_daily_drawdown_report['id_product']== 1 , 'id_product']= 'OD'
    filtered_daily_drawdown_report.dtypes
    # remave all staff segemts

    # filtered_daily_drawdown_report['drawdown_date']= pd.to_datetime(filtered_daily_drawdown_report['drawdown_date'], format='%Y-%m-%d', dayfirst = True).dt.strftime('%d-%m-%Y')
    filtered_daily_drawdown_report['drawdown_date']= pd.to_datetime(filtered_daily_drawdown_report['drawdown_date'])

    filtered_daily_drawdown_report['eom_date']= pd.to_datetime(filtered_daily_drawdown_report['eom_date'])

    # add branch name column
    filtered_daily_drawdown_report = pd.merge(filtered_daily_drawdown_report,branch_name_map, left_on ='unit_code', right_on ='brn_code', how ='left')
    filtered_daily_drawdown_report = filtered_daily_drawdown_report.rename(columns={'staff_branch':'branch_name'})
    filtered_daily_drawdown_report.drop(columns={'brn_code'}, inplace=True)

    #map code 100 to rehani
    filtered_daily_drawdown_report['branch_name'] = filtered_daily_drawdown_report.apply(lambda row:'REHANI BRANCH' if row['unit_code'] == 100 else row['branch_name'] , axis=1)

    filtered_daily_drawdown_report = pd.merge(filtered_daily_drawdown_report,segment_mapping, on='segment', how='left')

    filtered_daily_drawdown_report['month'] = pd.to_datetime(filtered_daily_drawdown_report['drawdown_date'], format='%d-%m-%Y').dt.strftime('%b-%Y')
    filtered_daily_drawdown_report['month']

    # function for determining if loan is short term

    def short_term_check(row):
        if row['main_segment'] == 'PERSONAL' and row['loan_term_months']< 48.1:
            return 'Y'
        elif row['main_segment'] == 'BB' and row['loan_term_months']< 48.1:
            return 'Y'
        elif row['main_segment'] == 'FI' and row['loan_term_months']< 48.1:
            return 'Y'
        elif row['main_segment'] == 'VIRTUAL':
            return 'Y'
        else:
            return 'N'

    filtered_daily_drawdown_report['short_term']= filtered_daily_drawdown_report.apply(short_term_check, axis =1)

    # check for loans done before 23/03/2024
    def eom_check(row):
        if row['eom_date'] < dt(2024,3,23):
            return 'Y'
        else:
            return 'N'

    # the check is only for the year 2024 and isn't needed moving forward
    # if report_year <= 2024:
    #     filtered_daily_drawdown_report['23-March-2024']= filtered_daily_drawdown_report.apply(eom_check, axis =1)

    # filtered_daily_drawdown_report['eom_date']= pd.to_datetime(filtered_daily_drawdown_report['eom_date']).dt.strftime('%d-%m-%Y')

    # filtered_daily_drawdown_report['eom_date']
    filtered_daily_drawdown_report.loc[filtered_daily_drawdown_report['sales_person'] == 'AL3116','sales_person']= 'AKL3116'
    filtered_daily_drawdown_report.loc[filtered_daily_drawdown_report['sales_person'] == 'SC3568','sales_person']= 'SJC3568'
    filtered_daily_drawdown_report.loc[filtered_daily_drawdown_report['sales_person'] == 'PK3453','sales_person']= 'PMK3453'
    filtered_daily_drawdown_report.loc[filtered_daily_drawdown_report['sales_person'] == 'AOL3199','sales_person']= 'AL3199'
    # in the case sales staff is empty
    filtered_daily_drawdown_report['sales_code'] = filtered_daily_drawdown_report.apply(lambda row: row['loan_officer_id'] if pd.isna(row['sales_person']) else row['sales_person'], axis=1)

    filtered_daily_drawdown_report['sales_code'] = filtered_daily_drawdown_report['sales_person'].str.strip()

    drawdown_salesperson_keep_columns =['sales_code','staff_name','staff_role','team_leader']
    drawdown_sales_person_mapping = sales_persons_targets_mapping_unique[drawdown_salesperson_keep_columns]

    filtered_daily_drawdown_report = pd.merge(filtered_daily_drawdown_report,drawdown_sales_person_mapping, on='sales_code', how='left')
    # filtered_daily_drawdown_report.drop(columns={'sales_code'}, inplace =True)
    filtered_daily_drawdown_report = filtered_daily_drawdown_report.rename(columns ={'product_desc':'product_name','staff_name':'rm_name','staff_role':'role'})
    filtered_daily_drawdown_report = filtered_daily_drawdown_report.sort_values(by='drawdown_date',ascending = True)
    
    drawdown_column_order = ['account_number','cust_id','customer_name','drawdown_date','sales_person','id_product',
                             'product_name','loan_officer_id','loan_officer_name','final_interest','loan_term_days',
                             'loan_term_months','unit_code','eom_date','net_drawdown','gross_drawdown','segment','financial_sector',
                             'activity_sector','diaspora_check','fkgd_category','description','branch_name','short_term','month','main_segment',
                             'sales_code','rm_name','role','team_leader']
    filtered_daily_drawdown_report =filtered_daily_drawdown_report[drawdown_column_order]

    return filtered_daily_drawdown_report

