    bancassurance_report['underwiter_mapping_to_britam'] = bancassurance_report['underwriter'].apply(lambda x:'Britam' if x in product_names else x)
    bancassurance_report.loc[bancassurance_report['product']=='FIRE INSURANCE - COMMERCIAL PROPERTIES','underwiter_mapping_to_britam']='Britam'
    bancassurance_report.loc[bancassurance_report['product']=='FIRE INSURANCE - RESIDENTIAL PROPERTIES','underwiter_mapping_to_britam']='Britam'
    bancassurance_report.loc[bancassurance_report['product']=='LIFE','underwiter_mapping_to_britam']='Britam'
    bancassurance_report.loc[bancassurance_report['product']=='LIFE INSURANCE','underwiter_mapping_to_britam']='Britam'
    bancassurance_report.loc[bancassurance_report['product']=='LIFE INSURANCE NO RETRENCHMENT 2025-4.5','underwiter_mapping_to_britam']='Britam'
    bancassurance_report.loc[bancassurance_report['product']=='LIFE INSURANCE WITH RETRENCHMENT','underwiter_mapping_to_britam']='Britam'
    bancassurance_report.loc[bancassurance_report['product']=='LIFE INSURANCE WITH RETRENCHMENT 2025-6','underwiter_mapping_to_britam']='Britam'
    bancassurance_report.loc[bancassurance_report['product']=='LIFE INSURANCE WITH RETRENCHMENT/WITHOUT','underwiter_mapping_to_britam']='Britam'
    bancassurance_report.loc[bancassurance_report['product']=='LIFE INSURANCE WITHOUT RETRENCHMENT','underwiter_mapping_to_britam']='Britam'
    bancassurance_report.loc[bancassurance_report['product']=='Life With Retrenchment','underwiter_mapping_to_britam']='Britam'
    bancassurance_report.loc[bancassurance_report['product']=='Life Without Retrenchment','underwiter_mapping_to_britam']='Britam'
    bancassurance_report.loc[bancassurance_report['product']=='LIFEPLUS INSURANCE','underwiter_mapping_to_britam']='Britam'


    vic_premium_condition = (bancassurance_report['underwriter'] !='Britam') & (bancassurance_report['underwriter'] !='Britam Life')& (bancassurance_report['vic_check'] == 'vic')
    bancassurance_report.loc[vic_premium_condition, 'vic_check'] = 'non-vic'
    bancassurance_report = bancassurance_report.sort_values(by ='starting_date')
    bancassurance_report = pd.merge(bancassurance_report,branch, on='branch', how='left')

    # bancassurance_report.drop(columns={'branch_1'}, inplace =True)
    bancassurance_report = bancassurance_report.rename(columns ={'branch_2':'branch_name'})

    bancassurance_report['branch_name'] = bancassurance_report.apply(lambda row:'HFCB-BI' if pd.isna(row['branch']) else row['branch_name'] , axis=1)
    bancassurance_salesperson_keep_columns =['sales_code','staff_role','team_leader']
    
    bancassurance_report = bancassurance_report.rename(columns={'paid_premiums':'paid_premiums_prev'})

    bancassurance_report["starting_date"] = pd.to_datetime(bancassurance_report["starting_date"])
    accrue_names = ['BRITAM HOLDINGS PLC']

    def accrue_value(row):
        if row["insured"] not in accrue_names:
            return row["paid_premiums_prev"]  

        start_month = row["starting_date"].month
        current_month = mtd_date.month

        if current_month < start_month:
            return 0  # not started yet
            
        total_months = 12 - start_month + 1
        monthly_value = row["paid_premiums_prev"] / total_months

        # full months accrued
        months_elapsed = current_month - start_month

        # total accrued including MTD for current month
        accrued = months_elapsed * monthly_value
        accrued += monthly_value * mtd_fraction

        return accrued

    bancassurance_report["paid_premiums_accrued"] = bancassurance_report.apply(accrue_value, axis=1)
    bancassurance_report = bancassurance_report.rename(columns={'paid_premiums_accrued':'paid_premiums'})



    # bancassurance_sales_person_mapping = sales_persons_targets[bancassurance_salesperson_keep_columns]
    bancassurance_sales_person_mapping = sales_persons_targets_mapping_unique[bancassurance_salesperson_keep_columns]

    bancassurance_report = pd.merge(bancassurance_report,bancassurance_sales_person_mapping, left_on ='code',right_on='sales_code', how='left')
    bancassurance_report['staff_role'] = bancassurance_report['staff_role'].fillna('Others')

    segment_map = [{'staff_role':'PB BBC','segment':'PERSONAL BANKING','segment_2':'PERSONAL BANKING'},
               {'staff_role':'SME BBC','segment':'BUSINESS BANKING','segment_2':'BUSINESS BANKING'},
               {'staff_role':'BANCA DSR','segment':'HFCB-BI','segment_2':'HFCB-BI'},
               {'staff_role':'BANCA BDO','segment':'HFCB-BI','segment_2':'HFCB-BI'},
               {'staff_role':'ULTIMATE RM','segment':'ULTIMATE','segment_2':'ULTIMATE'},
               {'staff_role':'SME RM','segment':'BUSINESS BANKING','segment_2':'BUSINESS BANKING'},
               {'staff_role':'SME ARM','segment':'BUSINESS BANKING','segment_2':'BUSINESS BANKING'},
               {'staff_role':'PB RM','segment':'PERSONAL BANKING','segment_2':'PERSONAL BANKING'},
               {'staff_role':'PB ARM','segment':'PERSONAL BANKING','segment_2':'PERSONAL BANKING'},
               {'staff_role':'PB DSR','segment':'PERSONAL BANKING','segment_2':'PERSONAL BANKING'},
               {'staff_role':'SME DSR','segment':'BUSINESS BANKING','segment_2':'BUSINESS BANKING'},
               {'staff_role':'COMMERCIAL RM','segment':'COMMERCIAL','segment_2':'COMMERCIAL'},
               {'staff_role':'DIASPORA RM','segment':'DIASPORA','segment_2':'DIASPORA'},
               {'staff_role':'DIASPORA ARM','segment':'DIASPORA','segment_2':'DIASPORA'},
               {'staff_role':'Business Development Manager','segment':'MORTGAGE','segment_2':'MORTGAGE'},
               {'staff_role':'MORTGAGE RM','segment':'MORTGAGE','segment_2':'MORTGAGE'},
               {'staff_role':'MORTGAGE ARM','segment':'MORTGAGE','segment_2':'MORTGAGE'},
               {'staff_role':'Property Advisor','segment':'PROPERTY','segment_2':'PROPERTY - SALES'},
               {'staff_role':'HFDI PA','segment':'PROPERTY','segment_2':'PROPERTY - SALES'},
               {'staff_role':'HFDI RO','segment':'PROPERTY','segment_2':'PROPERTY - SALES'},
               {'staff_role':'HFDI PM','segment':'PROPERTY','segment_2':'PROPERTY - PROJECT MANAGEMENT'},
               {'staff_role':'HFDI BDM','segment':'PROPERTY','segment_2':'PROPERTY - BUSINESS DEVELOPMENT'},
               {'staff_role':'HFDI DPB','segment':'PROPERTY','segment_2':'PROPERTY - DIGITAL PROPERTY'}
              ]
                   
    segment_mapping = pd.DataFrame(segment_map)

    bancassurance_report = pd.merge(bancassurance_report,segment_mapping,on ='staff_role', how='left')
    bancassurance_report['segment'] = bancassurance_report['segment'].fillna('OTHER SALES')

    # if the client is britam holdings, segemnt is hfbi
    bancassurance_report.loc[bancassurance_report['insured']=='BRITAM HOLDINGS PLC','segment']='HFCB-BI'


    bancassurance_report.loc[(bancassurance_report['branch_name'] == 'HFCB-BI') & (bancassurance_report['segment'] == 'OTHER SALES'),'segment'] = 'HFCB-BI'
    bancassurance_report.loc[(bancassurance_report['branch_name'] == 'PROPERTY') & (bancassurance_report['segment'] == 'OTHER SALES'),'segment'] = 'PROPERTY - SALES'


    # %%


    # Segment Esther Mulweye under Business Banking
    bancassurance_report.loc[bancassurance_report['sales_person']=='Esther Mulweye','staff_role']='TRADE FINANCE RM'
    bancassurance_report.loc[bancassurance_report['sales_person']=='Esther Mulweye','segment']='BUSINESS BANKING'


    # %%


    bancassurance_report.loc[bancassurance_report['staff_role']=='TRADE FINANCE RM','segment_2']='BUSINESS BANKING'


    # %%


