    bancassurance_report['segment_2'] = bancassurance_report['segment_2'].fillna('OTHER SALES')

    # for hfdi,default to hfdi sales if unmapped
    bancassurance_report.loc[(bancassurance_report['segment'] =='PROPERTY')&(bancassurance_report['segment_2'] == 'OTHER SALES'),'segment_2']='PROPERTY'

    
    # for hfdi,default to hfdi sales if unmapped
    bancassurance_report.loc[(bancassurance_report['segment'] =='PROPERTY')&(bancassurance_report['segment_2'] == 'OTHER SALES'),'segment_2']='HFDI SALES'
