"""## Loan Approvals Data"""

def process_loan_approvals_dataframe(loan_approvals_dump):
    
    loan_approvals_dump = loan_approvals_dump.rename(columns={'ApplicationId':'application_id', 'CreationDate':'creation_date',
                                                          'Branch':'branch', 'ProductCategory':'product_category', 'Product':'product',
                                                        'CustomerCategory':'customer_category', 'Customerid':'customer_id', 'FullName':'name',
                                                        'Currency':'currency','RequestedAmount':'amount_requested', 'ApprovedAmount':'amount_approved',
                                                        'DisbursementAmount':'amount_disbursed', 'StatusFrom':'status_from',
                                                        'ActionUserName':'action_user', 'StatusTo':'status_to', 'ActionDate':'action_date','ActionUser':'action_user',
                                                        'ActionUserNameRole':'action_user_role', 'AccountOfficer':'account_officer', 'Seller':'seller','SellerCode':'seller_code',
                                                        'createdAt':'created', 'updatedAt':'updated', 'Total_Bank_TAT':'total_bank_tat','ActionDate BRANCH APPLICATION':'branch_application',
                                                        'ActionDate BUSINESS ANALYSIS':'business_analysis','ActionDate CREDIT APPROVAL':'credit_approval','ActionDate OFFER LETTER GENERATION':'offer_letter_generation',
                                                        'ActionDate DRAWDOWN INITIATION CREDIT':'drawdown_initiation_credit','Product Name':'product_name','Product Class':'product_class', 'DateMonthDay':'month'})


                                     
    def get_approval_month(row):
        if pd.isna(row['offer_letter_generation']) or row['offer_letter_generation'] == "":
            return row['drawdown_initiation_credit']
        else:
            return row['offer_letter_generation']

    currency_map = {
        1: 'USD',
        22: 'KES',
        4: 'GBP',
        19: 'EUR',
        9: 'JPY',
        23: 'ZAR'
    }

    exchange_rate_map = {
        1: 129,
        22: 1,
        19: 139,
        9: 0.88,
        23: 7.55
    }
    
    loan_approvals_dump.loc[loan_approvals_dump['currency']== 0 , 'currency']= 22
    # loan_approvals_dump['action_date'] = pd.to_datetime(loan_approvals_dump['action_date'],dayfirst = True).dt.strftime('%d-%m-%Y')
    # loan_approvals_dump['created'] = pd.to_datetime(loan_approvals_dump['created'],dayfirst = True).dt.strftime('%d-%m-%Y')
    # loan_approvals_dump['updated'] = pd.to_datetime(loan_approvals_dump['updated'],dayfirst = True).dt.strftime('%d-%m-%Y')

    loan_approvals_dump['action_date'] = pd.to_datetime(loan_approvals_dump['action_date'],dayfirst = True)
