    loan_approvals_dump['business_analysis'] = pd.to_datetime(loan_approvals_dump['business_analysis'], errors='coerce')
    loan_approvals_dump['credit_approval'] = pd.to_datetime(loan_approvals_dump['credit_approval'], errors='coerce')
