    # convert all to lowercase
    loan_approvals_dump['status_to'] = loan_approvals_dump['status_to'].str.lower()

    # loan_approvals_dump['offer_letter_generation'] = pd.to_datetime(loan_approvals_dump['offer_letter_generation'], format='%d-%m-%Y',dayfirst=True, errors='coerce')
    # loan_approvals_dump['drawdown_initiation_credit'] = pd.to_datetime(loan_approvals_dump['drawdown_initiation_credit'], format='%d-%m-%Y',dayfirst=True, errors='coerce')

    loan_approvals_dump['approval_date'] = loan_approvals_dump.apply(get_approval_month, axis= 1)
    # Ensure it's datetime
    # loan_approvals_dump['approval_year'] = pd.to_datetime(loan_approvals_dump['approval_date'], errors='coerce').dt.strftime('%Y')
    loan_approvals_dump['approval_year'] = loan_approvals_dump['approval_date'].dt.strftime('%Y')

    filtered_loan_approvals_dump = loan_approvals_dump[loan_approvals_dump['approval_year'] == f'{report_year}']

    # filter out approvals that were cancelled only
    filtered_loan_approvals_dump=filtered_loan_approvals_dump[~(filtered_loan_approvals_dump['status_to'].str.contains("cancelled"))]

    # filter out approval amounts that are zero and/or blank
    filtered_loan_approvals_dump = filtered_loan_approvals_dump[(filtered_loan_approvals_dump['amount_approved'] != 0) & (filtered_loan_approvals_dump['amount_approved'] != '') & filtered_loan_approvals_dump['amount_approved'].notna()]

    # sort values by oldest creationdate & highest approval amount
    sorted_loan_approvals_dump = filtered_loan_approvals_dump.sort_values(by=['creation_date','amount_approved'], ascending = [True,False])

    sorted_loan_approvals_dump['currency_2'] = (
        pd.to_numeric(sorted_loan_approvals_dump['currency'], errors='coerce')
        .map(currency_map)
        .fillna('undefined')
    )

    sorted_loan_approvals_dump['rate'] = (
        pd.to_numeric(sorted_loan_approvals_dump['currency'], errors='coerce')
        .map(exchange_rate_map)
        .fillna(0)
    )

    sorted_loan_approvals_dump['approved_lcy_amount'] = sorted_loan_approvals_dump['amount_approved'] * sorted_loan_approvals_dump['rate']

