    # sorted_loan_approvals_dump['creation_date'] = pd.to_datetime(sorted_loan_approvals_dump['creation_date'], dayfirst = True).dt.strftime('%d-%m-%Y')
    # sorted_loan_approvals_dump['offer_letter_generation'] = pd.to_datetime(sorted_loan_approvals_dump['offer_letter_generation'],dayfirst = True).dt.strftime('%d-%m-%Y')
    # sorted_loan_approvals_dump['drawdown_initiation_credit'] = pd.to_datetime(sorted_loan_approvals_dump['drawdown_initiation_credit'],dayfirst = True).dt.strftime('%d-%m-%Y')

    # sorted_loan_approvals_dump['approval_date'] = pd.to_datetime(sorted_loan_approvals_dump['approval_date'],dayfirst = True).dt.strftime('%d-%m-%Y')

    # correct sales codes
    sorted_loan_approvals_dump.loc[sorted_loan_approvals_dump['seller_code'] == 'AL3116','seller_code']= 'AKL3116'
    sorted_loan_approvals_dump.loc[sorted_loan_approvals_dump['seller_code'] == 'SC3568','seller_code']= 'SJC3568'
    sorted_loan_approvals_dump.loc[sorted_loan_approvals_dump['seller_code'] == 'PK3453','seller_code']= 'PMK3453'
