    sorted_loan_approvals_dump.loc[sorted_loan_approvals_dump['seller_code'] == 'DWN3998','seller_code']= 'DN3998'
    

    # update sales codes for sales persons (only for ODs since they need to be manually changed)
    sorted_loan_approvals_dump.loc[sorted_loan_approvals_dump['application_id'] == 'CL8199','seller_code']= 'IN3692'
