    sorted_loan_approvals_dump.loc[sorted_loan_approvals_dump['application_id'] == 'CL8959','seller_code']= 'IN3692'
    sorted_loan_approvals_dump.loc[sorted_loan_approvals_dump['application_id'] == 'CL9472','seller_code']= 'LJB1656'
    sorted_loan_approvals_dump.loc[sorted_loan_approvals_dump['application_id'] == 'CL9476','seller_code']= 'LJB1656'
    sorted_loan_approvals_dump.loc[sorted_loan_approvals_dump['application_id'] == 'CL9470','seller_code']= 'LJB1656'
    sorted_loan_approvals_dump.loc[sorted_loan_approvals_dump['application_id'] == 'CL9203','seller_code']= 'LJB1656'
    sorted_loan_approvals_dump.loc[sorted_loan_approvals_dump['application_id'] == 'CL9506','seller_code']= 'LJB1656'
