"""## Trade Finance Data"""

def process_trade_finance_dataframe(trade_report):
  trade_report['issue_date']= pd.to_datetime(trade_report['issue_date'], format = '%d-%b-%Y', errors ='coerce')
  trade_report['expiry_date']= pd.to_datetime(trade_report['expiry_date'], format = '%d-%b-%Y', errors ='coerce')
  trade_report['month_name'] = pd.to_datetime(trade_report['month'], format = '%m').dt.strftime('%b')+f'-{report_year}'
  trade_report =trade_report.rename(columns={'rm_code':'sales_code'})

  return trade_report


