"""## Forex Data"""

def process_forex_dataframe(forex_report):
  def sort_branch(dataframe,sort_column):
      # Exclude the Total row
      df_without_last_row = dataframe.iloc[:-1].copy()
      df_without_last_row = df_without_last_row.sort_values(by='branch')

      # Get the Total row
      last_row = dataframe.iloc[-1:]

      # Reattach the Total row to the sorted DataFrame
      result_df = pd.concat([df_without_last_row, last_row])
      return result_df

  forex_report = sort_branch(forex_report,'branch')

  months = ['jan', 'feb', 'mar', 'apr',
        'may', 'jun', 'jul', 'aug', 'sep', 'oct',
        'nov', 'dec']
  
  # rename the month colums to pick month and report year & right in prper fomart
  forex_report = forex_report.rename(columns ={f'{month}_sum': f'{month.capitalize()}-{report_year}'for month in months})

  month_order = [f'{month}-{report_year}' for month in[ 'Jan','Feb','Mar', 'Apr','May','Jun', 'Jul', 'Aug','Sep','Oct','Nov','Dec']] 

  forex_column_order = ['branch', 'yesterday_revenue', 'mtd_sum', 'monthly_target',
                        'mtd_achieved', 'ytd_sum', 'ytd_target', 'ytd_achieved', 'fy_target',
                        'fytd_achieved']+ month_order + ['zone']

    
  forex_report = forex_report[forex_column_order]

  return forex_report


