"""## Safaricom and Bank Tills Data"""

# check if sales person is a DPA or PB DSR
def payment_check(row):
  if str(row['team_leader']).strip() == '' or pd.isna(row['team_leader']):
      return 'N'
  elif row['team_leader'] in  ['DSR149','DSR180','DSR193','DSR280'] :
      return 'Y'
  else:
      return 'Y'

# tills are dormant if reporting date miuus latest trx date is greater than 90 days
def active_till_check(row, report_date):
  latest_trx_date = row['latest_time_trx']
  if isinstance(latest_trx_date, str):
      latest_trx_date = dt.strptime(latest_trx_date, '%d-%m-%Y')

  report_date = dt.strptime(report_date,'%d-%b-%Y')

  days_difference = (report_date - latest_trx_date).days

  if days_difference <= 90:
      return 'Active'
  else:
      return 'Dormant'

def process_safaricom_tills_dataframe(safaricom_tills_report):
  safaricom_tills_report['biller_creation_date'] = pd.to_datetime(safaricom_tills_report['biller_creation_date'])
  safaricom_tills_report['first_time_trx'] = pd.to_datetime(safaricom_tills_report['first_time_trx'], errors='coerce')
  safaricom_tills_report['latest_time_trx'] = pd.to_datetime(safaricom_tills_report['latest_time_trx'], errors='coerce')
  # safaricom_tills_report['latest_time_trx'] = pd.to_datetime(safaricom_tills_report['latest_time_trx']).dt.strftime('%d-%m-%Y')
  safaricom_tills_report['month'] = safaricom_tills_report['first_time_trx'].dt.strftime('%b-%Y')

  # filter data by current year only when the till was first used
  filtered_safaricom_tills_report = safaricom_tills_report[safaricom_tills_report['first_time_trx'].dt.year == report_year]
  # filtered_safaricom_tills_report['biller_creation_date'] = pd.to_datetime(filtered_safaricom_tills_report['biller_creation_date'])
  # filtered_safaricom_tills_report['first_time_trx'] = pd.to_datetime(filtered_safaricom_tills_report['first_time_trx'])

  saf_tills_salesperson_keep_columns =['sales_code','team_leader']
  saf_tills_sales_person_mapping = sales_persons_targets_mapping_unique[saf_tills_salesperson_keep_columns]

  filtered_safaricom_tills_report = pd.merge(filtered_safaricom_tills_report,saf_tills_sales_person_mapping, on ='sales_code', how='left')
  filtered_safaricom_tills_report['sales_code'] = filtered_safaricom_tills_report['sales_code'].str.strip()


  filtered_safaricom_tills_report = pd.merge(filtered_safaricom_tills_report,saf_tills_branch_map, left_on ='branch_name', right_on='branch_1', how='left')
  filtered_safaricom_tills_report.drop(columns={'branch_1'}, inplace =True)
  filtered_safaricom_tills_report = filtered_safaricom_tills_report.rename(columns ={'branch_2':'branch'})
  filtered_safaricom_tills_report['payment_team_check'] = filtered_safaricom_tills_report.apply(payment_check, axis =1)
  filtered_safaricom_tills_report['active_check'] = filtered_safaricom_tills_report.apply(active_till_check,report_date = report_date, axis=1)

  return filtered_safaricom_tills_report

