"""## Tills Branch"""

def process_tills_branch_dataframe(branch_tills):
  # clean up -remove row if branch is blank
  branch_tills = branch_tills[branch_tills['branch'].notna()]

  branch_tills['generate_series'] = pd.to_datetime(branch_tills['generate_series'], errors ='coerce')

  branch_tills['months'] = pd.to_datetime(branch_tills['months'], errors ='coerce').dt.strftime('%b-%Y')

  # report data for the reorting year only
  branch_tills = branch_tills[branch_tills['generate_series'].dt.year== report_year]
  # branch_tills

  branch_tills['generate_series'] = pd.to_datetime(branch_tills['generate_series'], format = '%d-%m-%Y').dt.strftime('%d/%m/%Y')

  branch_tills = branch_tills.rename(columns= {'generate_series':'month', 'months':'month_name'})

  #remove space in the riverroad
  branch_tills.loc[branch_tills['branch']== 'River Road','branch']='RiverRoad'
  # update branch name 'SameerPark'
  branch_tills.loc[branch_tills['branch']== 'Sameer','branch']='SameerPark'

  #sort every month by branch name
  sorted_branch_tills = branch_tills.sort_values(by = ['month','branch'])
  return sorted_branch_tills


