# In[75]:


def roles_focus_funded_account_table(dataframe, index, month_column_name, value_column_name):
    focus_count = pd.pivot_table(dataframe, columns=month_column_name, index = index, values = value_column_name, aggfunc = 'count', margins = True, margins_name='total')
    focus_count = focus_count.fillna(0).reset_index()
    month_order = [f'{month}-{report_year}' for month in[ 'Jan','Feb','Mar', 'Apr','May','Jun', 'Jul', 'Aug','Sep','Oct','Nov','Dec']]  #define the month order
    present_columns = [col for col in month_order if col in focus_count.columns]
    for month in month_order:
        if  month not in focus_count.columns:
            focus_count[month]=0

    current_month_date = dt.strptime(f'{report_month}-{report_year}','%b-%Y')
    past_and_reporting_months = [month for month in month_order if dt.strptime(month,'%b-%Y') <= current_month_date]
    focus_count =focus_count[[index] + past_and_reporting_months +['total']]
    focus_count['total'] = focus_count[past_and_reporting_months].sum(axis=1)
    return focus_count


