"""## Loan Approvals"""

def get_loan_approval_amount(dataframe, index, month_column_name, value_column_name):
    month_order = [f'{month}-{report_year}' for month in['Jan','Feb','Mar', 'Apr','May','Jun', 'Jul', 'Aug','Sep','Oct','Nov','Dec']]  #define the month order

    current_month = dt.strptime(f'{report_month}-{report_year}','%b-%Y')
    past_and_reporting_months = [month for month in month_order if dt.strptime (month,'%b-%Y') <= current_month]

     
    if dataframe.empty:
        return pd.DataFrame(columns=[index] + past_and_reporting_months + ['Total'])

        
    approval_value = pd.pivot_table(dataframe, columns=month_column_name, index = index, values = value_column_name, aggfunc = 'sum', margins = True, margins_name='Total')
    approval_value = approval_value.fillna(0).reset_index()
          
  
    for month in month_order:
        if  month not in approval_value.columns:
            approval_value[month]=0
          
    approval_value['Total'] = approval_value[past_and_reporting_months].sum(axis=1)                          
    approval_value =approval_value[[index] + past_and_reporting_months +['Total']]   # ensure the branches are shown

    
    return approval_value

