def team_lead_new_deposits(dataframe, index, month_column_name, value_column_name):
  new_deposits = pd.pivot_table(dataframe, columns=month_column_name, index = index, values = value_column_name, aggfunc = 'sum', margins = True, margins_name='total')
  new_deposits = new_deposits.fillna(0).reset_index()

  month_order = [f'{month}-{report_year}' for month in ['Jan','Feb','Mar', 'Apr','May','Jun', 'Jul', 'Aug','Sep','Oct','Nov','Dec']]  #define the month order
  present_columns = [col for col in month_order if col in new_deposits.columns]
  for month in month_order:
      if  month not in new_deposits.columns:
          new_deposits[month]=0

  current_month_date = dt.strptime(f'{report_month}-{report_year}','%b-%Y')
  past_and_reporting_months = [month for month in month_order if dt.strptime(month,'%b-%Y') <= current_month_date]

  new_deposits =new_deposits[[index] + past_and_reporting_months +['total']]   # ensure the branches are shown

  new_deposits['total'] = new_deposits[past_and_reporting_months].sum(axis=1)

  return new_deposits

