"""### TLs - Focus Accounts"""

def team_lead_focus_account(dataframe, index, month_column_name, value_column_name):
  focus_vol = pd.pivot_table(dataframe, columns=month_column_name, index = index, values = value_column_name, aggfunc = 'count', margins = True, margins_name='total')
  focus_vol = focus_vol.fillna(0).reset_index()

  month_order = [f'{month}-{report_year}' for month in [ 'Jan','Feb','Mar', 'Apr','May','Jun', 'Jul', 'Aug','Sep','Oct','Nov','Dec']]  #define the month order
  present_columns = [col for col in month_order if col in focus_vol.columns]
  for month in month_order:
      if  month not in focus_vol.columns:
          focus_vol[month]=0

  current_month_date = dt.strptime(f'{report_month}-{report_year}','%b-%Y')
  past_and_reporting_months = [month for month in month_order if dt.strptime(month,'%b-%Y') <= current_month_date]

  focus_vol =focus_vol[[index] + past_and_reporting_months +['total']]   # ensure the branches are shown

  focus_vol['total'] = focus_vol[past_and_reporting_months].sum(axis=1)

  return focus_vol

team_lead_focus_account_table = team_lead_focus_account(dpa_filtered_funded_focus_accounts_data, month_column_name='account_date', index = 'team_leader',value_column_name = 'account_status')

