"""### TL - Drawdown"""

# filter drawdown data - net drawdown, sales staff codes only, month column
def tl_net_drawdown_amount(dataframe, index, month_column_name, value_column_name):
  tl_net_drawdown_value = pd.pivot_table(dataframe, columns=month_column_name, index = index, values = value_column_name, aggfunc = 'sum', margins = True, margins_name='total')
  tl_net_drawdown_value = tl_net_drawdown_value.fillna(0).reset_index()

  month_order = [ f'{month}-{report_year}' for month in ['Jan','Feb','Mar', 'Apr','May','Jun', 'Jul', 'Aug','Sep','Oct','Nov','Dec']]   #define the month order
  present_columns = [col for col in month_order if col in tl_net_drawdown_value.columns]
  for month in month_order:
      if  month not in tl_net_drawdown_value.columns:
          tl_net_drawdown_value[month]=0

        
#   if dataframe.empty:
#     cols = [index] + past_and_reporting_months + ['total']
#     return pd.DataFrame(columns=cols).fillna(0)      
  current_month_date = dt.strptime(f'{report_month}-{report_year}','%b-%Y')
  past_and_reporting_months = [month for month in month_order if dt.strptime(month,'%b-%Y') <= current_month_date]

  tl_net_drawdown_value =tl_net_drawdown_value[[index] + past_and_reporting_months +['total']]   # ensure the branches are shown

  tl_net_drawdown_value['total'] = tl_net_drawdown_value[past_and_reporting_months].sum(axis=1)

  return tl_net_drawdown_value

