def dpa_saf_till_volume(dataframe, index, month_column_name, value_column_name):
  till_volume = pd.pivot_table(dataframe, columns=month_column_name, index = index, values = value_column_name, aggfunc = 'count', margins = True, margins_name='total')
  till_volume = till_volume.fillna(0).reset_index()

  month_order = [  f'{month}-{report_year}' for month in ['Jan','Feb','Mar', 'Apr','May','Jun', 'Jul', 'Aug','Sep','Oct','Nov','Dec']]   #define the month order
  present_columns = [col for col in month_order if col in till_volume.columns]
  for month in month_order:
      if  month not in till_volume.columns:
          till_volume[month]=0

  current_month_date = dt.strptime(f'{report_month}-{report_year}','%b-%Y')
  past_and_reporting_months = [month for month in month_order if dt.strptime(month,'%b-%Y') <= current_month_date]

  till_volume =till_volume[[index] + past_and_reporting_months +['total']]   # ensure the branches are shown

  till_volume['total'] = till_volume[past_and_reporting_months].sum(axis=1)

  return till_volume

