def payment_till_value(dataframe, index, month_column_name, value_column_name):
  till_value = pd.pivot_table(dataframe, columns=month_column_name, index = index, values = value_column_name, aggfunc = 'sum', margins = True, margins_name='total')
  till_value = till_value.fillna(0).reset_index()

  month_order = [  f'{month}-{report_year}' for month in ['Jan','Feb','Mar', 'Apr','May','Jun', 'Jul', 'Aug','Sep','Oct','Nov','Dec']]   #define the month order
  present_columns = [col for col in month_order if col in till_value.columns]
  for month in month_order:
      if  month not in till_value.columns:
          till_value[month]=0

  current_month_date = dt.strptime(f'{report_month}-{report_year}','%b-%Y')
  past_and_reporting_months = [month for month in month_order if dt.strptime(month,'%b-%Y') <= current_month_date]

  till_value =till_value[[index] + past_and_reporting_months +['total']]   # ensure the branches are shown

  till_value['total'] = till_value[past_and_reporting_months].sum(axis=1)

  return till_value

