"""### TL - loan approvals"""

# filter drawdown data - net drawdown, sales staff codes only, month column
def tl_loan_approvals_amount(dataframe, index, month_column_name, value_column_name):
    month_order = [f'{month}-{report_year}' for month in['Jan','Feb','Mar', 'Apr','May','Jun', 'Jul', 'Aug','Sep','Oct','Nov','Dec']]  #define the month order

    current_month = dt.strptime(f'{report_month}-{report_year}','%b-%Y')
    past_and_reporting_months = [month for month in month_order if dt.strptime (month,'%b-%Y') <= current_month]

     
    if dataframe.empty:
        return pd.DataFrame(columns=[index] + past_and_reporting_months + ['total'])

        
    tl_loan_approvals_value = pd.pivot_table(dataframe, columns=month_column_name, index = index, values = value_column_name, aggfunc = 'sum', margins = True, margins_name='Total')
    tl_loan_approvals_value = tl_loan_approvals_value.fillna(0).reset_index()
          
  
    for month in month_order:
        if  month not in tl_loan_approvals_value.columns:
            tl_loan_approvals_value[month]=0
          
    tl_loan_approvals_value['total'] = tl_loan_approvals_value[past_and_reporting_months].sum(axis=1)                          
    tl_loan_approvals_value =tl_loan_approvals_value[[index] + past_and_reporting_months +['total']]   # ensure the branches are shown

    return tl_loan_approvals_value

tl_loan_approvals_table = tl_loan_approvals_amount(sorted_loan_approvals_dump, month_column_name='approval_month', index = 'team_leader',value_column_name = 'approved_lcy_amount')

dpa_tl_loan_approvals_table = pd.merge(dpa_team_leaders_targets,tl_loan_approvals_table, left_on ='team_leader', right_on ='team_leader', how ='left')
