dpa_tl_loan_approvals_table = dpa_tl_loan_approvals_table.rename(columns ={'annual_target_loan_approvals':'annual_targets','target_loan_approvals': 'monthly_targets','total':'ytd_actual'})
dpa_tl_loan_approvals_table = dpa_tl_loan_approvals_table.fillna(0)
month_order = [f'{month}-{report_year}' for month in ['Jan','Feb','Mar', 'Apr','May','Jun', 'Jul', 'Aug','Sep','Oct','Nov','Dec']]
present_columns = [col for col in month_order if col in dpa_tl_loan_approvals_table.columns]

