# Weighted Scores Formula

def get_payments_new_model_monthly_weighted_score(focus_data,net_drawdown_data,saf_till_volume_data,bank_till_volume_data,till_value_data,
                                        new_customer, till_transactions, new_deposits, approvals_data,banca_life_data,banca_non_life_data):
    # current the weight for month & year are the same
    focus_accounts_weight = 0.20
    drawdown_weight = 0.20
    saf_till_volume_weight = 0.10
    bank_till_volume_weight = 0.20
    till_value_weight = 0.25
    new_customer_weight = 0
    till_transactions_weight = 0
    loan_approvals_weight  = 0.0
    # properties_weight = 0
    new_deposits_weight = 0
    banca_life_weight = 0.025
    banca_non_life_weight = 0.025
    allocated_monthly_weight = 0.6

    monthly_weighted_score = (focus_data['current_month_score']* focus_accounts_weight) + (net_drawdown_data['current_month_score'] * drawdown_weight)+(saf_till_volume_data['current_month_score'] * saf_till_volume_weight) + (till_value_data['current_month_score'] * till_value_weight)+ (new_customer['current_month_score'] * new_customer_weight)+(till_transactions['current_month_score'] * till_transactions_weight) +  (bank_till_volume_data['current_month_score'] * bank_till_volume_weight) + (new_deposits['current_month_score'] * new_deposits_weight) +(approvals_data['current_month_score'] * loan_approvals_weight) +(banca_life_data['current_month_score'] * banca_life_weight)+(banca_non_life_data['current_month_score'] * banca_non_life_weight)

    return monthly_weighted_score

def get_payments_new_model_ytd_weighted_score(focus_data,net_drawdown_data,saf_till_volume_data,bank_till_volume_data,till_value_data,new_customer, 
                                    till_transactions, new_deposits,approvals_data,banca_life_data,banca_non_life_data):
    # current the weight for month & year are the same
    focus_accounts_weight = 0.20
    drawdown_weight = 0.20
    saf_till_volume_weight = 0.10
    bank_till_volume_weight = 0.20
    till_value_weight = 0.25
    new_customer_weight = 0
    till_transactions_weight = 0
    loan_approvals_weight  = 0.0
    # properties_weight = 0
    new_deposits_weight = 0
    banca_life_weight = 0.025
    banca_non_life_weight = 0.025
    allocated_ytd_weight = 0.4

    ytd_weighted_score = (focus_data['ytd_score']* focus_accounts_weight) + (net_drawdown_data['ytd_score'] * drawdown_weight)+(saf_till_volume_data['ytd_score'] * saf_till_volume_weight) + (till_value_data['ytd_score'] * till_value_weight)+ (new_customer['ytd_score'] * new_customer_weight)+(till_transactions['ytd_score'] * till_transactions_weight) + (bank_till_volume_data['ytd_score'] * bank_till_volume_weight) + (new_deposits['ytd_score'] * new_deposits_weight) + (approvals_data['ytd_score'] * loan_approvals_weight)+(banca_life_data['ytd_score'] * banca_life_weight)+(banca_non_life_data['ytd_score'] * banca_non_life_weight)

    return ytd_weighted_score


