def dsrs_leaders_calculation_formulas(df):
    column_name = f'{report_month}-{report_year}' # this gives current month and current year
    if column_name in df.columns:
        df['current_month_actuals'] = df[column_name]

    else:
        df['current_month_actuals'] = 0

    if 'monthly_targets' in df.columns:
        # dsrs_persons_count = 22.5  # 22.5 is set number of persons for each as at July 2025 & 12 is the number of months in a year
        
        emanuel_dsrs_persons_count = 30  # ~number as approved by GM as at (May 2026)
        lucyann_dsrs_persons_count = 30  # ~number of people in the team as at (May 2026)
        df.loc[df['team_leader'] == 'Ian','annual_targets'] = df['monthly_targets'] * lucyann_dsrs_persons_count * 12
        df.loc[df['team_leader'] == 'Emanuel','annual_targets'] = df['monthly_targets'] * emanuel_dsrs_persons_count * 12

        # df['annual_targets'] = (df['monthly_targets'] * (dsrs_persons_count*12))  
        df['monthly_targets'] = df['annual_targets']/12
        df['current_month_score'] = (df['current_month_actuals'] / df['monthly_targets']).clip(lower= 0,upper=1.2)
        df['ytd_target'] = df['annual_targets'] * ytd_fraction
        df['mtd_target'] = df['monthly_targets'] * mtd_fraction
        if 'ytd_actual' in df.columns:
            df['ytd_score'] = (df['ytd_actual'] / df['ytd_target']).clip(lower=0,upper=1.2)
        else:
            df['ytd_score'] =0

    return df


