"""## Weighted Scores"""

def get_pb_dsrs_monthly_weighted_score(new_customer,focus_data,net_drawdown_data,loan_approvals, new_deposits,life_banca_data,non_life_banca_data):
    # currently the weight for month & year are the same
    focus_accounts_weight = 0.20
    drawdown_weight = 0.35
    new_customer_weight = 0.20
    new_deposits_weight = 0.20
    life_banca_weight = 0.02
    non_life_banca_weight = 0.03
    loan_approvals_weight = 0.00
    
    allocated_monthly_weight = 0.70

    pb_dsr_monthly_weighted_score = (loan_approvals['current_month_score']* loan_approvals_weight) + (focus_data['current_month_score']* focus_accounts_weight) + (net_drawdown_data['current_month_score'] * drawdown_weight)+ (new_customer['current_month_score'] * new_customer_weight)+(life_banca_data['current_month_score'] * life_banca_weight)+ (non_life_banca_data['current_month_score'] * non_life_banca_weight)  + (new_deposits['current_month_score'] * new_deposits_weight)
    return pb_dsr_monthly_weighted_score

def get_pb_dsrs_ytd_weighted_score(new_customer,focus_data,net_drawdown_data, loan_approvals,new_deposits,life_banca_data,non_life_banca_data):

    # current the weight for month & year are the same
    focus_accounts_weight = 0.20
    drawdown_weight = 0.35
    new_customer_weight = 0.20
    new_deposits_weight = 0.20
    # properties_weight = 0.00
    non_life_banca_weight = 0.03
    life_banca_weight = 0.02
    loan_approvals_weight = 0.00
    
    allocated_ytd_weight = 0.30

    pb_dsr_ytd_weighted_score = (loan_approvals['ytd_score']* loan_approvals_weight) + (focus_data['ytd_score']* focus_accounts_weight) + (net_drawdown_data['ytd_score'] * drawdown_weight)+ (new_customer['ytd_score'] * new_customer_weight)+(life_banca_data['ytd_score'] * life_banca_weight)+ (non_life_banca_data['ytd_score'] * non_life_banca_weight)  + (new_deposits['ytd_score'] * new_deposits_weight)
    return pb_dsr_ytd_weighted_score

def calculate_dsrs_weighted_score(df):
    allocated_monthly_weight = 0.7
    allocated_ytd_weight = 0.3

    weighted_score = (df['monthly_weighted_score']* allocated_monthly_weight) + (df['ytd_weighted_score'] * allocated_ytd_weight)

    return weighted_score


