def apply_new_model_dsr_rank_column(
    new_model_dsrs_df_lists,
    weighted_column='weighted_score',
    rank_column='rank'
):
    if not new_model_dsrs_df_lists:
        return []

    # Rank only on the first DataFrame (excluding total row)
    first_df = new_model_dsrs_df_lists[0]
    first_df_without_total = first_df.iloc[:-1].copy()
    total_row = first_df.iloc[[-1]].copy()

    # Assign ranks (do not sort)
    first_df_without_total[rank_column] = (
        first_df_without_total[weighted_column]
        .rank(ascending=False, method='dense')
        .astype(int)
    )

    # Reattach total row (its rank stays NaN)
    new_model_dsrs_df_lists[0] = pd.concat(
        [first_df_without_total, total_row],
        ignore_index=True
    )

    # Leave all other DataFrames unchanged
    return new_model_dsrs_df_lists

