# In[288]:


def apply_month_and_ytd_weights(
    weight_lists,
    df_lists,
    month_column='current_month_score',
    mw_column='monthly_weighted_score',
    ytd_column='ytd_score',
    ytd_weighted_column='ytd_weighted_score',
    weighted_column='weighted_score',
    rank_column='rank'
):
    if not df_lists or not weight_lists:
        return []

    # Initialize new DataFrames for weighted scores
    new_dfs = []
    for df in df_lists[-1]:  # Use structure of last metric
        new_df = pd.DataFrame(index=df.index)
        new_df[mw_column] = 0.0
        new_df[ytd_weighted_column] = 0.0
        new_df[weighted_column] = 0.0
        new_dfs.append(new_df)

    # Calculate weighted scores
    for i, new_df in enumerate(new_dfs):
        for weight_list, source_dfs in zip(weight_lists, df_lists):
            if i >= len(weight_list) or i >= len(source_dfs):
                continue
            weight = weight_list[i]
            source_df = source_dfs[i]

            month_scores = pd.to_numeric(source_df.get(month_column, 0.0), errors='coerce').reindex(new_df.index).fillna(0.0)
            ytd_scores = pd.to_numeric(source_df.get(ytd_column, 0.0), errors='coerce').reindex(new_df.index).fillna(0.0)

            new_df[mw_column] += month_scores * weight
            new_df[ytd_weighted_column] += ytd_scores * weight
            new_df[weighted_column] += (month_scores * weight * 0.5) + (ytd_scores * weight * 0.5)

    # Assign ranks to weighted score DataFrames (optional – not used for sorting)
    for new_df in new_dfs:
        ranks = new_df.iloc[:-1][weighted_column].rank(method='dense', ascending=False)
        new_df.loc[ranks.index, rank_column] = ranks
        new_df.loc[new_df.index[-1], rank_column] = None  # "Total" row

    # Apply rank to original df_lists[i][j], but DO NOT sort
    for i in range(len(df_lists)):
        for j in range(len(df_lists[i])):
            df = df_lists[i][j]
            rank_series = new_dfs[j][rank_column]
            df[rank_column] = rank_series.reindex(df.index).values

            # No sorting or index reset

            # Drop rank column in all except the first list of dfs
            if i != 0 and rank_column in df.columns:
                df.drop(columns=[rank_column], inplace=True)

    # Reorder columns in df_lists[0] to bring rank_column to front (optional)
    for j, df in enumerate(df_lists[0]):
        cols = df.columns.tolist()
        if rank_column in cols:
            cols.insert(0, cols.pop(cols.index(rank_column)))
            df_lists[0][j] = df[cols]

    # Return new_dfs without sorting or dropping rank
    return new_dfs


