"""## Weighted Scores"""

def get_commercial_monthly_weighted_score(focus_data,net_drawdown_data,new_customer,new_deposits, trade_finance,loan_approvals,savings, motor_banca_data, non_motor_banca_data):
    # current the weight for month & year are the same
    focus_accounts_weight = 0.15
    drawdown_weight = 0.35
    new_customer_weight = 0.2
    # properties_weight = 0
    new_deposits_weight = 0.15
    trade_finance_weight = 0.05
    loan_approvals_weight = 0.0
    savings_weight = 0.05
    banca_motor_weight = 0.02
    banca_non_motor_weight = 0.03

    allocated_monthly_weight = 0.5

    monthly_weighted_score = (focus_data['current_month_score'] * focus_accounts_weight) + (net_drawdown_data['current_month_score'] * drawdown_weight)+ (trade_finance['current_month_score'] * trade_finance_weight) +  (savings['current_month_score'] * savings_weight)+  (new_customer['current_month_score'] * new_customer_weight)+ (loan_approvals['current_month_score'] * loan_approvals_weight) +  (motor_banca_data['current_month_score'] * banca_motor_weight) +  (non_motor_banca_data['current_month_score'] * banca_non_motor_weight) +  (new_deposits['current_month_score'] * new_deposits_weight)
    return monthly_weighted_score

commercial_monthly_weighted_score =  get_commercial_monthly_weighted_score(loan_approvals = merged_commercial_rms_loan_approvals_tables, savings = merged_commercial_rms_savings_tables , trade_finance = merged_commercial_rms_trade_finance_tables, focus_data = merged_commercial_rms_focus_accounts_tables,net_drawdown_data=merged_commercial_rms_disbursements_tables,new_customer = merged_commercial_new_customers_table,new_deposits = merged_commercial_rms_new_deposits_tables,motor_banca_data = merged_commercial_rms_motor_bancassurance_tables,non_motor_banca_data = merged_commercial_rms_non_motor_bancassurance_tables)

def get_commercial_ytd_weighted_score(focus_data,net_drawdown_data,new_customer,new_deposits, trade_finance,loan_approvals,savings, motor_banca_data, non_motor_banca_data):
    # current the weight for month & year are the same
    focus_accounts_weight = 0.15
    drawdown_weight = 0.35
    new_customer_weight = 0.2
    # properties_weight = 0
    new_deposits_weight = 0.15
    trade_finance_weight = 0.05
    loan_approvals_weight = 0.0
    savings_weight = 0.05
    banca_motor_weight = 0.02
    banca_non_motor_weight = 0.03




    allocated_monthly_weight = 0.5


    monthly_weighted_score = (focus_data['ytd_score']* focus_accounts_weight) + (net_drawdown_data['ytd_score'] * drawdown_weight)+(trade_finance['ytd_score'] * trade_finance_weight) + (savings['ytd_score'] * savings_weight)+ (new_customer['ytd_score'] * new_customer_weight)+(loan_approvals['ytd_score'] * loan_approvals_weight) + (motor_banca_data['ytd_score'] * banca_motor_weight) + (non_motor_banca_data['ytd_score'] * banca_non_motor_weight) + (new_deposits['ytd_score'] * new_deposits_weight)
    return monthly_weighted_score

commercial_ytd_weighted_score =  get_commercial_ytd_weighted_score(loan_approvals = merged_commercial_rms_loan_approvals_tables, savings = merged_commercial_rms_savings_tables , trade_finance = merged_commercial_rms_trade_finance_tables, focus_data = merged_commercial_rms_focus_accounts_tables,net_drawdown_data=merged_commercial_rms_disbursements_tables,new_customer = merged_commercial_new_customers_table,new_deposits = merged_commercial_rms_new_deposits_tables,motor_banca_data = merged_commercial_rms_motor_bancassurance_tables,non_motor_banca_data = merged_commercial_rms_non_motor_bancassurance_tables)

