def apply_commercial_rank_column(
    commercial_df_lists,
    weighted_column='weighted_score',
    rank_column='rank'  # rank column to be created
):
    if not commercial_df_lists:
        return []

    # only for the first df
    first_df = commercial_df_lists[0]
    first_df_without_total = first_df.iloc[:-1].copy()
    total_row = first_df.iloc[[-1]].copy()

    first_df_without_total[rank_column] = (
        first_df_without_total[weighted_column]
        .rank(ascending=False, method='dense')
        .astype(int)
    )

    # # store the rank order to apply to other dataframes
    # rank_series = first_df_without_total[rank_column].reset_index(drop=True)

    # # apply rank order to the rest of the dataframes
    # for i in range(1, len(commercial_df_lists)):
    #     df = commercial_df_lists[i]
    #     df_without_total = df.iloc[:-1].copy()
    #     df_total_row = df.iloc[[-1]].copy()

    #     df_without_total[rank_column] = rank_series
    #     sorted_df = pd.concat(
    #         [df_without_total.sort_values(by=[rank_column]), df_total_row],
    #         ignore_index=True
    #     )
    #     sorted_df = sorted_df.drop(columns = [rank_column])
    #     commercial_df_lists[i] = sorted_df

    # # Sort and update the first dataframe with its calculated ranks
    # first_sorted_df = pd.concat(
    #     [first_df_without_total.sort_values(by=[rank_column]), total_row],
    #     ignore_index=True
    # )
    # commercial_df_lists[0] = first_sorted_df

    # Reattach total row (its rank stays NaN)
    commercial_df_lists[0] = pd.concat(
        [first_df_without_total, total_row],
        ignore_index=True
    )


    
    return commercial_df_lists




