"""# Branches & Zones

## New Customers
"""

# branch_targets.columns

def branch_new_customers(dataframe, index, month_column_name, value_column_name):
  new_customers_value = pd.pivot_table(dataframe, columns=month_column_name, index = index, values = value_column_name, aggfunc = 'count', margins = True, margins_name='total')
  new_customers_value = new_customers_value.fillna(0).reset_index()

  month_order = [f'{month}-{report_year}' for month in ['Jan','Feb','Mar', 'Apr','May','Jun', 'Jul', 'Aug','Sep','Oct','Nov','Dec']]  #define the month order
  present_columns = [col for col in month_order if col in new_customers_value.columns]
  for month in month_order:
      if  month not in new_customers_value.columns:
          new_customers_value[month]=0

  current_month_date = dt.strptime(f'{report_month}-{report_year}','%b-%Y')
  past_and_reporting_months = [month for month in month_order if dt.strptime(month,'%b-%Y') <= current_month_date]

  new_customers_value =new_customers_value[[index] + past_and_reporting_months +['total']]

  new_customers_value['total'] = new_customers_value[past_and_reporting_months].sum(axis=1)

  return new_customers_value

branch_new_customers_table = branch_new_customers(filtered_new_customers_data, month_column_name='customer_date', index = 'brn_code',value_column_name = 'account_status')

