def get_branch_savings_value(dataframe, index, month_column_name, value_column_name):
  savings_value = pd.pivot_table(dataframe, columns=month_column_name, index = index, values = value_column_name, aggfunc = 'sum', margins = True, margins_name='total')
  savings_value = savings_value.fillna(0).reset_index()

  month_order = [  f'{month}-{report_year}' for month in ['Jan','Feb','Mar', 'Apr','May','Jun', 'Jul', 'Aug','Sep','Oct','Nov','Dec']]   #define the month order
  present_columns = [col for col in month_order if col in savings_value.columns]
  for month in month_order:
      if  month not in savings_value.columns:
          savings_value[month]=0

  current_month_date = dt.strptime(f'{report_month}-{report_year}','%b-%Y')
  past_and_reporting_months = [month for month in month_order if dt.strptime(month,'%b-%Y') <= current_month_date]

  savings_value =savings_value[[index] + past_and_reporting_months +['total']]   # ensure the branches are shown

  savings_value['total'] = savings_value[past_and_reporting_months].sum(axis=1)

  return savings_value

