"""## Bancassurance"""

def get_branch_paid_premiums(dataframe, index, month_column_name, value_column_name):
  paid_premiums_value = pd.pivot_table(dataframe, columns=month_column_name, index = index, values = value_column_name, aggfunc = 'sum', margins = True, margins_name='total')
  paid_premiums_value = paid_premiums_value.fillna(0).reset_index()

  month_order = [f'{month}-{report_year}' for month in ['Jan','Feb','Mar', 'Apr','May','Jun', 'Jul', 'Aug','Sep','Oct','Nov','Dec']]   #define the month order
  present_columns = [col for col in month_order if col in paid_premiums_value.columns]

     # incase they is no data for the month, add the month column with zero values
  for month in month_order:
      if  month not in paid_premiums_value.columns:
          paid_premiums_value[month]=0

  # past_and_reporting_months = [ col for col in month_order if col  <= f'{report_month}-{report_year}']
  # paid_premiums_value =paid_premiums_value[[index] + past_and_reporting_months +['total']]   # ensure the branches are shown

  current_month_date = dt.strptime(f'{report_month}-{report_year}','%b-%Y')
  past_and_reporting_months = [month for month in month_order if dt.strptime(month,'%b-%Y') <= current_month_date]

  paid_premiums_value =paid_premiums_value[[index] + past_and_reporting_months +['total']]
  paid_premiums_value['total'] = paid_premiums_value[past_and_reporting_months].sum(axis=1)

  return paid_premiums_value

