def get_branch_monthly_weighted_score(new_customer,focus_data,net_drawdown_data, dormancy_data,forex_data,till_transactions,savings_data,banca_data):
    # current the weight for month & year are the same
    new_customer_weight = 0.3
    focus_accounts_weight = 0.125
    drawdown_weight = 0.075
    dormancy_weight = 0
    forex_weight = 0.15
    till_value_weight = 0.15
    savings_weight = 0.125
    banca_weight = 0.075
    allocated_monthly_weight = 0.5


    branch_monthly_weighted_score = (new_customer['current_month_score'] * new_customer_weight) + (focus_data['current_month_score']* focus_accounts_weight) + (net_drawdown_data['current_month_score'] * drawdown_weight) + (forex_data['current_month_score'] * forex_weight)+(till_transactions['current_month_score'] * till_value_weight)+(savings_data['current_month_score'] * savings_weight)+(banca_data['current_month_score'] * banca_weight)
    return branch_monthly_weighted_score

