    focus_accounts_weight = 0.125
    drawdown_weight = 0.075
    dormancy_weight = 0
    forex_weight = 0.15
    till_value_weight = 0.15
    savings_weight = 0.125
    banca_weight = 0.075
    allocated_ytd_weight = 0.5


    branch_ytd_weighted_score = (new_customer['ytd_score'] * new_customer_weight) + (focus_data['ytd_score']* focus_accounts_weight) + (net_drawdown_data['ytd_score']* drawdown_weight) + (forex_data['ytd_score'] * forex_weight)+(till_transactions['ytd_score'] * till_value_weight)+(savings_data['ytd_score'] * savings_weight)+(banca_data['ytd_score'] * banca_weight)
    return branch_ytd_weighted_score

