#                          home_specialists_focus_table,
#                          home_specialists_drawdown_table,
#                          home_specialists_loan_approvals_table]

def apply_home_specialists_month_and_ytd_weights(
    home_specialists_weights_lists,
    home_specialists_lists,
    month_column='current_month_score',
    mw_column='monthly_weighted_score',
    ytd_column='ytd_score',
    ytd_weighted_column='ytd_weighted_score',
    weighted_column='weighted_score',
    rank_column= 'rank'

):

    if not home_specialists_lists or not home_specialists_weights_lists:
        return []

    # Create new empty DataFrames with the same structure as df_lists[-1]
    new_dfs = []
    for df in home_specialists_lists[-1]:
        new_df = pd.DataFrame(index=df.index)
        new_df[mw_column] = 0.0
        new_df[ytd_weighted_column] = 0.0
        new_df[weighted_column] = 0.0
        new_dfs.append(new_df)

    # Compute weighted scores in the new DataFrames
    for i, new_df in enumerate(new_dfs):
        for weight_list, source_dfs in zip(home_specialists_weights_lists, home_specialists_lists):
            if i >= len(weight_list) or i >= len(source_dfs):
                continue

            source_df = source_dfs[i]

            # Monthly weighted score
            if month_column in source_df.columns:
                month_scores = pd.to_numeric(source_df[month_column], errors='coerce').fillna(0.0)
                new_df[mw_column] += month_scores * weight_list[i]

            # YTD weighted score
            if ytd_column in source_df.columns:
                ytd_scores = pd.to_numeric(source_df[ytd_column], errors='coerce').fillna(0.0)
                new_df[ytd_weighted_column] += ytd_scores * weight_list[i]

                new_df[weighted_column] += ((month_scores * weight_list[i]) *0.5) +((ytd_scores * weight_list[i]) *0.5)
                
        valid_rows = new_df.iloc[:-1] if len(new_df) > 1 else new_df

        ranks = valid_rows[weighted_column].rank(method='first', ascending=False).astype(int)
        new_df.loc[valid_rows.index, rank_column] = ranks

        # Ensure total row has blank / NaN rank
        if len(new_df) > 1:
            new_df.loc[new_df.index[-1], rank_column] = None
           
    # Return BOTH the original df_lists AND the new weighted DataFrames
    return home_specialists_lists + [new_dfs]  # Appends new_dfs as a new list after df_lists

homespecialists_scores = apply_home_specialists_month_and_ytd_weights(home_specialists_weights_lists,home_specialists_lists)
homespecialists_ytd_and_month_weighted_scores = homespecialists_scores[-1]


