"""## Weighted Scores"""

new_customer_weight = [0.20,0.20]
focus_accounts_weight =[ 0.10, 0.10]
new_deposits_weight = [0.20, 0.20]
savings_weight = [0.10, 0.10]
drawdown_weight =[ 0.25, 0.25]
loan_approvals_weight = [0.10, 0.10]
motor_banca_weight = [0.02, 0.02]
non_motor_banca_weight = [0.03, 0.03]

total_diaspora_weight = new_customer_weight+focus_accounts_weight+new_deposits_weight+savings_weight+drawdown_weight+loan_approvals_weight+motor_banca_weight+non_motor_banca_weight

diaspora_weights_lists =[new_customer_weight,
                         focus_accounts_weight,
                         new_deposits_weight,
                         savings_weight,
                         drawdown_weight,
                         loan_approvals_weight,
                         motor_banca_weight,
                         non_motor_banca_weight]

diaspora_lists =[merged_diaspora_new_customers_table,
                 merged_diaspora_rms_focus_accounts_tables,
                 merged_diaspora_rms_new_deposits_tables,
                 merged_diaspora_rms_savings_tables,
                 merged_diaspora_rms_disbursements_tables,
                 merged_diaspora_rms_loan_approvals_tables,
                 merged_diaspora_rms_motor_bancassurance_tables,
                 merged_diaspora_rms_non_motor_bancassurance_tables]


def apply_diaspora_month_and_ytd_weights(
    diaspora_weights_lists,
    diaspora_lists,
    month_column='current_month_score',
    mw_column='monthly_weighted_score',
    ytd_column='ytd_score',
    ytd_weighted_column='ytd_weighted_score',
    weighted_column='weighted_score',
    rank_column= 'rank'

):

    if not diaspora_lists or not diaspora_weights_lists:
        return []

    # Create new empty DataFrames with the same structure as df_lists[-1]
    new_dfs = []
    for df in diaspora_lists[-1]:
        new_df = pd.DataFrame(index=df.index)
        new_df[mw_column] = 0.0
        new_df[ytd_weighted_column] = 0.0
        new_df[weighted_column] = 0.0
        new_dfs.append(new_df)

    # Compute weighted scores in the new DataFrames
    for i, new_df in enumerate(new_dfs):
        for weight_list, source_dfs in zip(diaspora_weights_lists, diaspora_lists):
            if i >= len(weight_list) or i >= len(source_dfs):
                continue

            source_df = source_dfs[i]

            # Monthly weighted score
            if month_column in source_df.columns:
                month_scores = pd.to_numeric(source_df[month_column], errors='coerce').fillna(0.0)
                new_df[mw_column] += month_scores * weight_list[i]

            # YTD weighted score
            if ytd_column in source_df.columns:
                ytd_scores = pd.to_numeric(source_df[ytd_column], errors='coerce').fillna(0.0)
                new_df[ytd_weighted_column] += ytd_scores * weight_list[i]

                new_df[weighted_column] += ((month_scores * weight_list[i]) *0.5) +((ytd_scores * weight_list[i]) *0.5)
                
        valid_rows = new_df.iloc[:-1] if len(new_df) > 1 else new_df

        ranks = valid_rows[weighted_column].rank(method='first', ascending=False).astype(int)
        new_df.loc[valid_rows.index, rank_column] = ranks

        # Ensure total row has blank / NaN rank
        if len(new_df) > 1:
            new_df.loc[new_df.index[-1], rank_column] = None
           
    # Return BOTH the original df_lists AND the new weighted DataFrames
    return diaspora_lists + [new_dfs]  # Appends new_dfs as a new list after df_lists

diaspora_scores = apply_diaspora_month_and_ytd_weights(diaspora_weights_lists,diaspora_lists)
diapora_ytd_and_month_weighted_scores = diaspora_scores[-1]
diapora_ytd_and_month_weighted_scores


