"""## Branch Sheet"""

new_customers_tables = [zone_new_customers_table,branch_new_customers_table]
focus_account_tables = [zone_focus_table,branch_focus_accounts_table]
net_drawdown_tables = [zone_net_drawdown_table,branch_net_drawdown_table]
dormancy_tables = [zone_dormancy_table,branch_account_dormancy_table]
forex_tables = [zone_forex_table, branch_forex_table]
till_transactions_tables = [zone_till_transactions_table,branch_till_transactions_value_table]
savings_value_tables =[zone_savings_value_table,branch_savings_table]
bancassurance_tables = [zone_paid_premiums_table,paid_premiums_branch_table]
weighted_score_tables =[zone_month_and_ytd_weighted_scores,branch_month_and_ytd_weighted_scores]


#################################################### NEW CUSTOMERS ##################################################################################
start_row = 1
# start_col = 2 if i==0 else 0

rows = np.cumsum([df.shape[0]+3 for df in new_customers_tables]) # skip 3 rows after each df
fin_rows = [start_row] + [ data + start_row for data in rows[:len(rows)-1]]
fin_rows = [int(item) for item in fin_rows]

for i, (row,df) in enumerate(zip(fin_rows,new_customers_tables)):
    start_col = 3 if i==0 else 0
    df.to_excel(weighted_sales_report_writer, sheet_name = branch_sheet_name, startrow = row, startcol = start_col,index = False)

    branch_worksheet = weighted_sales_report_writer.sheets[branch_sheet_name]

for i, (row,df) in enumerate(zip(fin_rows,new_customers_tables)):

    start_col = 3 if i==0 else 0
    end_row = df.shape[0]+ row
    end_col = df.shape[1] + start_col-1
    branch_worksheet.merge_range(row-1,5, row-1,end_col,'NEW CUSTOMERS(30%)',royal_blue_format)
    branch_worksheet.set_column(start_col,end_col,16.00,number_format)
    branch_worksheet.conditional_format(row,start_col,end_row,end_col,{'type':'no_errors','format':border_format})
    branch_worksheet.conditional_format(row,start_col,row,end_col,{'type':'no_errors','format':royal_blue_format})
    branch_worksheet.conditional_format(row +1,9,end_row-1,end_col-3,{'type':'no_errors','format':month_fill_format})
    branch_worksheet.conditional_format(row +1,9,end_row-1,end_col-3,{'type':'no_errors','format':number_format})
    branch_worksheet.conditional_format(end_row,start_col,end_row,end_col,{'type':'no_errors','format':royal_blue_format})
    branch_worksheet.conditional_format(row + 1,5,end_row-1,6,{'type':'no_errors','format':fill_format})

    if 'current_month_score' in df.columns and 'ytd_score' in df.columns  and 'weighted_score' in df.columns:
        month_perc_col = df.columns.get_loc('current_month_score')
        ytd_perc_col = df.columns.get_loc('ytd_score')
        weighted_perc_col = df.columns.get_loc('weighted_score')

        branch_worksheet.conditional_format(row +1,start_col+month_perc_col,end_row,start_col+month_perc_col,{'type':'cell','criteria':'<', 'value':0.8, 'format': red_format})
        branch_worksheet.conditional_format(row +1,start_col+month_perc_col,end_row,start_col+month_perc_col,{'type':'cell','criteria':'>=', 'value':1.0, 'format': green_format})
        branch_worksheet.conditional_format(row +1,start_col+month_perc_col,end_row,start_col+month_perc_col,{'type':'cell','criteria':'between', 'minimum':0.8, 'maximum':1.0,'format': amber_format})
        branch_worksheet.conditional_format(row +1,start_col+ytd_perc_col,end_row,start_col+ytd_perc_col,{'type': 'no_errors', 'format': ytd_grey_format})
        branch_worksheet.conditional_format(row +1,start_col+weighted_perc_col,end_row,start_col+weighted_perc_col,{'type': 'no_errors', 'format': ytd_grey_format})

    # header = ['zone', 'branch']
    # for (row,title) in zip(fin_rows, header):
    #     # end_row = df.shape[0]+ row
    #     # end_col = df.shape[1] -1

    #     branch_worksheet.merge_range(row-1,start_col, row-1,start_col+1, title,vivid_tangerine_header_format)


#group & hide month clumns
    group_start_col = 10
    end_col = df.shape[1]+start_col -4
#     column_range = f'{xlsxwriter.utility.xl_col_to_name(group_start_col)}:{xlsxwriter.utility.xl_col_to_name(end_col)}'
    column_range = f'J:{xlsxwriter.utility.xl_col_to_name(end_col)}'

    branch_worksheet.set_column(column_range, None, None, {'level':1, 'hidden':True})


#################################################### FOCUS ACCOUNTS ##################################################################################

rows = np.cumsum([df.shape[0]+3 for df in focus_account_tables]) # skip 3 rows after each df
fin_rows = [start_row] + [ data + start_row for data in rows[:len(rows)-1]]
fin_rows = [int(item) for item in fin_rows]

focus_start_col =[ new_customers_tables[i].shape[1]+  3 if i==0 else new_customers_tables[i].shape[1] for i in range(len(focus_account_tables))]
for i, (col,df) in enumerate(zip(focus_start_col,focus_account_tables)):
    df.to_excel(weighted_sales_report_writer, sheet_name = branch_sheet_name, startrow = fin_rows[i], startcol = col,index = False)

    branch_worksheet = weighted_sales_report_writer.sheets[branch_sheet_name]

# for i, (row,df) in enumerate(zip(fin_rows,focus_account_tables)):
#     start_col = 2 if i==0 else 0
