start_row = 1

rows = np.cumsum([df.shape[0]+3 for df in pb_dsrs_new_customers_tables])
fin_rows = [start_row] + [ data + start_row for data in rows[:len(rows)-1]]
fin_rows = [int(item) for item in fin_rows]

for i, (row,df) in enumerate(zip(fin_rows,pb_dsrs_new_customers_tables)):

    start_col = 4 if i ==0 else 0  # start in the 3rd col for the first df
    df.to_excel(weighted_sales_report_writer, sheet_name = pb_dsr_sheet_name, startrow = row, startcol = start_col,index = False)

    pb_dsr_worksheet = weighted_sales_report_writer.sheets[pb_dsr_sheet_name]

    end_row = df.shape[0] + row
    end_col = df.shape[1] + start_col - 1

    title = 'PB_DSR_TEAM_LEADER'  if i == 0 else 'PB_DSR'

    pb_dsr_worksheet.merge_range(row-1,start_col, row-1,start_col+1, title,vivid_tangerine_header_format)
    pb_dsr_worksheet.merge_range(row-1,8, row-1,end_col,'NEW CUSTOMERS(20%)',royal_blue_format)
    pb_dsr_worksheet.set_column(start_col,end_col, 16.00,number_format)

    pb_dsr_worksheet.conditional_format(row,start_col,row,end_col,{'type':'no_errors','format':cell_wrap_format})
    pb_dsr_worksheet.conditional_format(row-1,start_col,end_row,end_col,{'type':'no_errors','format':border_format})
    pb_dsr_worksheet.conditional_format(row,start_col,row,end_col,{'type':'no_errors','format':royal_blue_format})
    pb_dsr_worksheet.conditional_format(row +1,14,end_row-1,end_col-3,{'type':'no_errors','format':month_fill_format}) # from January
    pb_dsr_worksheet.conditional_format(end_row,start_col,end_row,end_col,{'type':'no_errors','format':royal_blue_format})
    pb_dsr_worksheet.conditional_format(row + 1,9,end_row-1,11,{'type':'no_errors','format':fill_format})

    if 'current_month_score' in df.columns and 'ytd_score' in df.columns and 'weighted_score' in df.columns:
        # if i == 0:
        month_perc_col = df.columns.get_loc('current_month_score')
        ytd_perc_col = df.columns.get_loc('ytd_score')
        weighted_perc_col = df.columns.get_loc('weighted_score')


        pb_dsr_worksheet.conditional_format(row +1,start_col + month_perc_col,end_row,start_col + month_perc_col,{'type':'cell','criteria':'<', 'value':0.8, 'format': red_format})
        pb_dsr_worksheet.conditional_format(row +1,start_col + month_perc_col,end_row,start_col + month_perc_col,{'type':'cell','criteria':'>=', 'value':1.0, 'format': green_format})
        pb_dsr_worksheet.conditional_format(row +1,start_col + month_perc_col,end_row,start_col + month_perc_col,{'type':'cell','criteria':'between', 'minimum':0.8, 'maximum':1.0,'format': amber_format})
        pb_dsr_worksheet.conditional_format(row +1,start_col + ytd_perc_col,end_row,start_col + ytd_perc_col,{'type': 'no_errors', 'format': ytd_grey_format})
        pb_dsr_worksheet.conditional_format(row +1,start_col + weighted_perc_col,end_row,start_col + weighted_perc_col,{'type': 'no_errors', 'format': ytd_grey_format})




