fin_rows = [start_row] + [ data + start_row for data in rows[:len(rows)-1]]
fin_rows = [int(item) for item in fin_rows]

for i,(row,df) in enumerate(zip(fin_rows,merged_home_specialist_new_customers_table)):
    df.to_excel(weighted_sales_report_writer, sheet_name = home_specialist_sheet_name, index= False, startrow= row, startcol = start_col)
    home_specialist_worksheet = weighted_sales_report_writer.sheets[home_specialist_sheet_name]

