    end_row = df.shape[0] + row
    end_col = df.shape[1] + start_col - 1


    home_specialist_worksheet.merge_range(row-1,5, row-1,end_col,'NEW CUSTOMERS(20%)',royal_blue_format)
    home_specialist_worksheet.set_column(start_col,end_col, 16.00,number_format)
    
    home_specialist_worksheet.conditional_format(row,start_col,row,end_col,{'type':'no_errors','format':cell_wrap_format})
    home_specialist_worksheet.conditional_format(row-1,start_col,end_row,end_col,{'type':'no_errors','format':border_format})
    home_specialist_worksheet.conditional_format(row,start_col,row,end_col,{'type':'no_errors','format':royal_blue_format})
    home_specialist_worksheet.conditional_format(row +1,9,end_row-1,end_col-3,{'type':'no_errors','format':month_fill_format}) # from January
