    home_specialist_worksheet.conditional_format(row +1,5,end_row-1,6,{'type':'no_errors','format':fill_format})


    if 'current_month_score' in df.columns and 'ytd_score' in df.columns:
        # if i == 0:
        month_perc_col = df.columns.get_loc('current_month_score')
        ytd_perc_col = df.columns.get_loc('ytd_score')
        # weighted_perc_col = df.columns.get_loc('weighted_score')


        home_specialist_worksheet.conditional_format(row +1,start_col + month_perc_col,end_row,start_col + month_perc_col,{'type':'cell','criteria':'<', 'value':0.8, 'format': red_format})
        home_specialist_worksheet.conditional_format(row +1,start_col + month_perc_col,end_row,start_col + month_perc_col,{'type':'cell','criteria':'>=', 'value':1.0, 'format': green_format})
        home_specialist_worksheet.conditional_format(row +1,start_col + month_perc_col,end_row,start_col + month_perc_col,{'type':'cell','criteria':'between', 'minimum':0.8, 'maximum':1.0,'format': amber_format})
        home_specialist_worksheet.conditional_format(row +1,start_col + ytd_perc_col,end_row,start_col + ytd_perc_col,{'type': 'no_errors', 'format': ytd_grey_format})


   
    # if 'current_month_score' in merged_home_specialist_new_customers_table.columns and 'ytd_score' in merged_home_specialist_new_customers_table.columns and 'weighted_score' in merged_home_specialist_new_customers_table.columns:
