# In[352]:


def calculate_total_rows(dfs, group_col='branch', rank_col='rank', total_col='sales_code'):
    base_col = dfs[0][group_col]
    if isinstance(base_col, pd.DataFrame):
        base_col = base_col.iloc[:, 0]
    base_group = base_col.values

    results = []
    for i, df in enumerate(dfs):
        temp = df.copy()

        if group_col not in temp.columns:
            temp[group_col] = base_group

        subtotals = []
        for group, data in temp.groupby(group_col, sort=False):
            subtotals.append(data)

            # sum the values for all sales persons in a branch
            subtotal_row = data.sum(numeric_only=True).to_frame().T

            # get averages instead of sums for the score columns
            for col in ['weighted_score', 'monthly_weighted_score', 'ytd_weighted_score']:
                if col in data.columns:
                    subtotal_row[col] = data[col].mean()

            # -ytd_score
            if {'ytd_actual', 'ytd_target'}.issubset(data.columns):
                subtotal_row['ytd_score'] = (data['ytd_actual'].sum() / data['ytd_target'].sum()if data['ytd_target'].sum() != 0 else 0)
 
            if {'month_actual', 'monthly_target'}.issubset(data.columns):
                subtotal_row['monthly_score'] = (data['month_actual'].sum() / data['monthly_target'].sum()if data['monthly_target'].sum() != 0 else 0)

            subtotal_row[group_col] = group
            subtotal_row[total_col] = 'TOTAL'
            subtotals.append(subtotal_row)

        subtotals_df = pd.concat(subtotals, ignore_index=True)

        # --- grand total ---
        grand_total = temp.sum(numeric_only=True).to_frame().T

        # averages for grand total
        for col in ['weighted_score', 'monthly_weighted_score', 'ytd_weighted_score']:
            if col in temp.columns:
                grand_total[col] = temp[col].mean()

        # ratios for grand total
        if {'ytd_actual', 'ytd_target'}.issubset(temp.columns):
            grand_total['ytd_score'] = (
                temp['ytd_actual'].sum() / temp['ytd_target'].sum()
                if temp['ytd_target'].sum() != 0 else 0
            )

        if {'month_actual', 'monthly_target'}.issubset(temp.columns):
            grand_total['monthly_score'] = (
                temp['month_actual'].sum() / temp['monthly_target'].sum()
                if temp['monthly_target'].sum() != 0 else 0
            )

        grand_total[total_col] = 'GRAND TOTAL'

        final_df = pd.concat([subtotals_df, grand_total], ignore_index=True)

        if i != 0:
            cols_to_drop = [col for col in [group_col, rank_col] if col in final_df.columns]
            final_df = final_df.drop(columns=cols_to_drop)

        results.append(final_df)

    return results


