# In[383]:


def color_mtd_percentage(val):
    if not isinstance(val, (int, float)):
        return ''
    if val < 0.80:
        return 'background-color: #C0504D; color: black'
    elif val < 1.00:
        return 'background-color: #C69500; color: black'
    return 'background-color: #70AD47; color: black'

def color_ytd_percentage(val):
    if not isinstance(val, (int, float)):
        return ''
    return 'background-color: #D9D9D9; color: black'


# In[384]:


def style_branch_actuals(dataframe):
    format_dict = { col: lambda x: f"{x:,.0f}" for col in dataframe.columns if col not in ["current_month_score",'ytd_score'] }
    format_dict['ytd_score'] = '{:.0%}'
    format_dict["current_month_score"]='{:.0%}'
    
    def style_total_row(s):
        is_total_row = s.name == (len(dataframe) - 1)
        styles = [f'background-color: #1B4872; color: white; font-weight: bold' if is_total_row else '' for _ in s]
        return styles
    return dataframe.set_index(['branch_lines']).style \
          .format(format_dict) \
          .map(color_mtd_percentage, subset=['current_month_score']) \
          .map(color_ytd_percentage, subset=['ytd_score']) \
          .apply(style_total_row, axis=1) \
          .set_properties(**{
              'border': '1px solid black',
              'border-collapse': 'collapse',
              'border-spacing': '0'
          }) \
          .set_table_styles([{
              'selector': 'th',
              'props': [
                  ('border', '2px solid black'),
                  ('color', 'white'),
                  ('background-color', '#1B4872')
              ]
          }, {
              'selector': '',
              'props': [
                    ('border', '2px solid black'),
                    ('padding', '0 2px'),
                    ('font-size', '12px')
              ]
          }, {
              'selector': 'tbody > tr:last-child',
              'props': [
                  ('border', '1px solid black'),
                  ('color', 'white'),
                  ('background-color', '#1B4872'),
                  ('font-weight','bold')
              ]
          }])


style_branch_actuals(branch_chart_values)


